NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'Matthew'

CHAPTERS = {
    1: {
        1: 'PUK en di kan, me Iesus Kristus, me sapwilim en Dawid, me sapwilim en Apraam, tapi sang ia.',
        2: 'Apraam me wiadar Isaak, a Isaak me wiadar Iakop, a Iakop me wiadar Iuda o ri a ol akan;',
        3: 'A Iuda me wiadar Pares i Sara ren Tamar; a Pares me wiadar Esrom, a Esrom me wiadar Aram;',
        4: 'A Aram me wiadar Aminadap, a Aminadap me wiadar Naason, a Naason me wiadar Salmon;',
        5: 'A Salmon me wiadar Poas ren Raap, a Poas me wiadar Oped ren Rud, a Oped me wiadar Iese:',
        6: 'A Iese me wiadar nanmarki Dawid, a Dawid me wiadar Salomo ren li odi en Urias;',
        7: 'A Salomo me wiadar Reapeam, a Reapeam me wiadar Apia, a Apia me wiadar Asa;',
        8: 'A Asa me wiadar Iosapat, a Iosapat me wiadar Ioram, a Ioram me wiadar Usia;',
        9: 'A Usia me wiadar Iotam, a lotam me wiadar Aas, a Aas me wiadar Iskia;',
        10: 'A Iskia me wiadar Manase, a Manase me wiadar Amon, a Amon me wiadar Iosia;',
        11: 'A losia me wiadar Iekonia o ri a ol akan ni ansaun arail salilang Papilon.',
        12: 'Murin arail salidi nan Papilon Iekonia me wiadar Sealtiel, a Sealtiel me wiadar Serupapel;',
        13: 'A Serupapel me wiadar Apiud, a Apiud me wiadar Eliakim, a Eliakim me wiadar Asor;',
        14: 'A Asor me wiadar Sadok, a Sadok me wiadar Akim, a Akim me wiadar Eliud;',
        15: 'A Eliud me wiadar Eliaser, a Eliaser me wiadar Matan, a Matan me wiadar Iakop;',
        16: 'A Iakop me wiadar Iosep, me likondeki Maria, me kaipwiedi Iesus, me maraneki Kristus.',
        17: 'Di karos sang ren Apraam lei Dawid me eisokpaieu; a sang Dawid lei arail salidi nan Papilon di eisokpaieu; a sang arail salidi nan Papilon lei Kristus di eisokpaieu.',
        18: 'Nan iet duen Kristus a kotin ipwidier: Ni ansau me in a Maria kisin nin ong Iosep, a diarokadar, me a liseanekier Ngen saraui mon ara tu pena.',
        19: 'A a warok Iosep ol pung amen, ap sota men kanamenokala i, ap kupukupura, en rir muei sang i.',
        20: 'A ni a kotin madamadaue duen mepukat, kilang, tounlang en Kaun o pwara dong i ni a aliman masani: Iosep nain Dawid koe, der masak, en ale om warok Maria, pwe Ngen saraui me a lisean kidar.',
        21: 'A pan kaipwiedi seri ol amen, me koe pan ki ong mar a Iesus, pwe a pan dorela sapwilim a aramas akan sang nin dip arail.',
        22: 'Mepukat karos wiauier, pwen pwaida me lokido sang Kaun ren saukop o, me masani:',
        23: 'Kilang seripein makelekel o pan liseanda, ap kaipwiedi seri ol amen, irail ari pan ki ong mar a Imanuel; iet wewe: Kot me kotin ieiang kitail.',
        24: 'Iosep lao pirida sang a saimok, ap kapwaiadar, me tounlang en Kaun o kotin kakalik ong i o apapwali a likond.',
        25: 'A ap sota pweidi re a, lao a kaipwiedier sapwilim a meseni ol, ap kotiki ong mar a Iesus.',
    },
    2: {
        1: 'A IESUS lao ipwidier Petleem nan Iudäa ni muein nanmarki Erodes, kilang ol lolekong kai ap pwarado sang ni mas en Iang ko dong Ierusalem, kalelapok:',
        2: 'Ia Nanmarki en Sus akan, me apton ipwidier, kotikot ia? Pwe se kilanger a usu ni sap en mas en lang ap pwarado, pwen pongi i.',
        3: 'A nanmarki Erodes lao rongadar mepukat, ap landar o toun Ierusalem karos,',
        4: 'Ap kupokon pena samero lapalap karos o sounkawewe en aramas akan kainoma re’rail, wasa Kristus pan ipwidi ia.',
        5: 'Irail ari potoan ong i: Nan Petleem en Iudäa; pwe iduen a intingidi ren saukop o:',
        6: 'A koe Petleem, sap en Iuda, kaidin me tikitik nan pung en saupeidi en Iuda kan; pwe Kaun amen pan tapi sang uk, me pan kaunda nai aramas en Israel akan.',
        7: 'Erodes ap kawai pena ol lolekong kan, kalelapok mau re’rail ansau o, me usu o pwarado.',
        8: 'I ari porone ir alang Petleem masani: Komail kowei raparapaki mau seri o; a komail lao diaradar, en kaireki dong ia, pwe i en pil kola pongi i.',
        9: 'Irail lao ronger nanmarki o ap koieila. A kilang usu o, me irail kilanger nan sap en mas en lang, ti ong mo’rail, a lao udi ong wasa o, me seri pwelel kotikot ia.',
        10: 'Irail lao kilanger usu o, re ap peren kida kaualapia.',
        11: 'Irail lao pedelong ong nan im o, re ap masanier seri pwelel o in a Maria, re ap kaipokedi o pongi i, o kapwaredar arail kapwa kan, ap mairongki ong i kold, o men pomau, o mire.',
        12: 'Kot ap kotin pangoki ong irail ni arail auramen, en der purelang Erodes, re ap weidwei ni apot al purelang sap arail.',
        13: 'Irail lao samalar, kilang tounlang en Kaun amen ap pwara dong ren Iosep ni a aliman masani: Paurida, ale seri pwelel en o in a tangwei lang Äkipten o kaukauson wasa o, I lao kaire kin uk, pwe Erodes pan rapaki seri pwelel o pwen kamatala.',
        14: 'I ari kipada, aleer seri pwelel o in a ni pong, kotilang Äkipten;',
        15: 'O kaukauson ia, lao en Erodes a matala, pwen pwaida, me lokido sang Kaun o, ren saukop o me masani: Sang nan Äkipten me I ekeredo nai ol o.',
        16: 'Erodes lao mangier, me a sarokidier ol lolekong kan, ap ongiong kidar kaualap o poronelan, kamela seri ol karos, me mi Petleem o nan sap salong karos, me saunpar riau o tikitik sang, duen ansau me a kalelapok mau ren me lolekong kan.',
        17: 'I dokan a pwaidar me lokido ren saukop Ieremia me masani:',
        18: 'Ngil eu wiauier nan Rama, sangesang o maiei laud; Rael sangesangki na seri kan, a kang insenemaula, pwe irail soer mia.',
        19: 'A Erodes lao matalar, kilang tounlang en Kaun amen ap pwara dong ren Iosep nan Äkipten ni a aliman,',
        20: 'Masani: Paurida ale seri pwelel en o in a, ko wong nan sap en Israel, pwe irail melar, me rapaki, pwen kamela seri pwelel o.',
        21: 'I ari kipadar, ale seri pwelel o in a, pure dong sap en Israel.',
        22: 'A lao mangi, me Arkelaus kaunda Iudäa wiliandi sam a Erodes, ap lan kotilang wasa o. Kot ap kotin pangoki ong i ni a aliman, ap kotilang sap en Kaliläa kai.',
        23: 'O kotido kotikot nan kanim eu me adaneki Nasaret, pwen pwaida, me lokido ren saukop akan: A pan maraneki men Nasaret.',
    },
    3: {
        1: 'A NI ran pukat Ioanes saunpaptais pwarado, padapadak nan sap en Iudäa,',
        2: 'Masani: Komail kalula, pwe wein nanlang korendor.',
        3: 'Pwe iei i, me saukop Iesaia katitiki, masani: Ngil en saunkair amen nan sap tan: Komail kaonopada al en Kaun o, kainenela al a!',
        4: 'A i Ioanes me a likau wun en kamel o a pirapireki kil in man, a sak a mansiek o oni en nan wel.',
        5: 'Toun Ierusalem, o toun Iudäa, o toun sap akan liman Iordan ap koieila re a;',
        6: 'O irail paptaisela re a nan Iordan, ni ar weokada dip arail akan.',
        7: 'A lao masanier Parisär o Sadusar me toto ko dong a paptais, ap masani ong irail: Dakot wan oter komail! Is me padaki ong komailer, en piti sang ni kamekam me kokodo?',
        8: 'Ari, komail kapwareda wan kalula mau!',
        9: 'A komail depa lamelame, me komail pan indang pein komail: Nan Apraam sam atail. Pwe i indai ong komail, me Kot kotin kak ong wiaki ong Apraam na seri kai takai pukat.',
        10: 'Sile o mier ni tapin tuka kan; a tuka karos me so wa mau, pan paledi o lokidokila nani iai.',
        11: 'Melel, i paptais kin komail pil ong kalula, a me kotido muri, nan me laude sang ia, ngai sowar ong, en wa sapwilim a sut; i me pan paptais kin komail Ngen saraui o kisiniai.',
        12: 'Sapwilim a tanir mi ni lim a; a pan kotin koko melel sapwilim a pera, ap nekid pena sapwilim a wan korn nan im en nak, a dip akan a pan kotin karong kila kisiniai soutuk.',
        13: 'Iesus ap kotido sang Kaliläa, koti dong Iordan ren Ioanes, pwen paptaisela re a.',
        14: 'A Ioanes kotin kang, ap potoan ong: Mak eta i en paptaisela re ir, a iaduen ir me kotido re i?',
        15: 'A Iesus kotin sapeng masani ong i: Wiada mas, pwe me kon ong kita, en kapwuiada pung kan karos; a ap duki ong i.',
        16: 'Iesus lao paptaiselar, ap kotin madangada sang nan pil o. A kilang, nanlang ap ritidang i, i ari kotin masani Ngen en Kot kotidido ni mom en muroi men a kaipokedi po a.',
        17: 'O kilang, ngil eu sang nanlang masani: Iet nai ol kompok, me I kin polaule kida!',
    },
    4: {
        1: 'IESUS ap kotin kakaluadala ren Ngen nan sap tan, pwen songesong ren tewil.',
        2: 'A lao kotin kaisesolar ran pangaul o pon pangaul ap men sak.',
        3: 'Men kasongesong ap pwara dong i indada: Ma komui Sapwilim en Kot, en masani, takai pukat en wiala prot.',
        4: 'A kotin sapeng masani: A intingidier: Kaidin prot eta, me aramas kin memaureki, pwe masan akan karos, me kin pwili sang nin silang in Kot.',
        5: 'Tewil ap kalualang i nan kanim saraui o kauada i pon kongkong en kaudok,',
        6: 'Indang i: Ma komui Sapwilim en Kot, kasedi pein komui, pwe a intingidier: A pan kasilaki sapwilim a tounlang kan komui, o irail pan wa komui ni lim ar akan, pwe aluwilu omui ede dipikelekel ni takai eu.',
        7: 'Iesus kotin masani ong i: A pil intingidier: Koe der kasongesong Kot om Kaun.',
        8: 'Tewil ap pil kaluadalang i pon nana ileile kaualapia eu o kasale ong i wein sappa karos o a lingan,',
        9: 'Indang i: Mepukat karos i pan ki ong komui, ma komui men poridi o pongi ong ia.',
        10: 'Iesus ap kotin masani ong i: Ko sang ia Satan, pwe a intingidier: Koe en pongi ong Kot om Kaun, i eta koe en papa.',
        11: 'Tewil ap muei sang i, a kilang, tounlang kan ap pwarado papa ong i.',
        12: 'A lao mangier, me Ioanes salidier, ap kotilang Kaliläa,',
        13: 'O a kotin muei sang Nasaret, kotido kaukausonla Kapernaum, me mi ni kailan sed impan sap Sepulon o Naptalim;',
        14: 'Pwen pwaida, me lokido ren saukop Iesaia me masani:',
        15: 'Sap Sepulon o sap Naptalim, me sal ong sed, palilan Iordan, o Kaliläa en men liki kan,',
        16: 'Aramas akan, me momod nan rotorot, kilanger marain lapalap eu, o irail me momod nan sap en mot en mela, marain eu dakar irail adar.',
        17: 'I dokan Iesus kotin tapiadar padapadak o mamasani: Kalula, pwe wein nanlang korendor.',
        18: 'A lao kotikot sili pon oror en lein Kaliläa, ap masanier pirien eu, Simon, me adaneki Petrus, o ri a Andreas, me kadukaduedi ara uk nan sed, pwe ira me saused.',
        19: 'A ap kotin masani ong ira: Idauen ia do, I pan wia kin koma saused en aramas!',
        20: 'Ira madang muei sang uk akan o idauenla i.',
        21: 'A ni a kotila sang wasa o, ap pil masani eu pirien, Iakopus, nain Sepedäus o ri a Ioanes, me mi nin sop ren sam ara Sepedäus, wonewone ara uk akan. I ari kotin molipe ira do.',
        22: 'Ira madang muei sang sop o sam ara ap idauenla i.',
        23: 'Iesus ari kotin kakan sili nan Kaliläa kaukawewe nan arail sinakoke kan o padapadak rongamau en wei, o kotin kakelada song en somau o luet akan karos nan pung en aramas akan.',
        24: 'I ari indant sili nan Sirien pon. O irail wa dong i me somau kan karos, me aneki song en somau o wairok kai, o me tewil ti poa kan, o me pwepwe kan, o me rerer akan, i ari kotin kakela ir ada.',
        25: 'Pokon kalaimun me idauenla i sang Kaliläa o Dekapolis, o Ierusalem, o Iudäa, o sang palilan Iordan.',
    },
    5: {
        1: 'A LAO masani pokon o, ap kotida pong dol eu; a lao kaipokedi, sapwilim a tounpadak kan ap kai dong i.',
        2: 'I ari kotin dauasa pasang silang i kawewe ong irail masani:',
        3: 'Meid pai, me samama ni ngen ir, pwe nairail wein nanlang.',
        4: 'Meid pai, me mauk, pwe re pan kamaitala.',
        5: 'Meid pai, me opampap, pwe re pan sosoki sappa.',
        6: 'Meid pai, me kin men manga o men nim me pung, pwe re pan medila.',
        7: 'Meid pai, me kadek, pwe re pan diar kadek.',
        8: 'Meid pai, me nan mongiong arail makelekel, pwe re pan ariri Kot.',
        9: 'Meid pai, me kin tom pena, pwe re pan adaneki seri en Kot.',
        10: 'Meid pai, me kamekameki pung, pwe nairail wein nanlang.',
        11: 'Komail meid pai, ma irail lalaue o paki komail o palian komail ni arail lokaia sued o likam pweki ngai.',
        12: 'Komail insenemau o perenda kaualap; pweki katinge pamail me lapalap nanlang. Pwe iduen irail paki saukop oko, me mo’mail.',
        13: 'Sol pan sappa komail. A ma sol sara sang, da me a pan soleki? Nan a pan me mal kot, men lokidokila, o aramas en tiak pasang.',
        14: 'Marain pan sappa komail, Kanim eu, me mi pon dol eu, sota kak rirla.',
        15: 'Aramas pil sota kin isikeda lamp eu, ap ki ong pan kasak, pwe pon deu a, o a kin kamaraini toun im karos.',
        16: 'Iduen omail marain en sansal mon aramas, pwe irail en udial omail wiawia man kan, ap kapikapinga Sam omail, me kotiluit nanlang.',
        17: 'Eder kikiong me I kodon, tiakedi kapung de saukop akan. I sota kodon tiakedi, a pwen kapwaiada.',
        18: 'Pwe melel, I indai ong komail, lao lang o sappa pan poula, sota iota eu de kisin muai en kapung eu pan lokidokila, lao karos pan pwaida.',
        19: 'Ari, meamen me tiakedi eu kisin kusoned tikitik pukat, ap pil padaki ong aramas, ren tiakedi, nan a pan tikitik nan wein nanlang. A meamen, me oke o padaki ong aramas, ren oke, i me pan lapalap nan wein nanlang.',
        20: 'Pwe I indai ong komail, ma omail pung so man sang pung en saunkawewe o Parisär, akan, komail sota pan kak pedelon ong nan wein nanlang.',
        21: 'Komail rongadar, me a loki, ong men kaua: Koe der kamela aramas! A me pan kamela aramas, pan pangalang kadeik o.',
        22: 'A I indai ong komail, meamen makarada mal pan ri a ol, pan pangalang kadeik. A me pan indang ri a ol: Raka, pan pangalang kapung. A me pan inda: Koe me pweipwei, pan lokidokila nan le en pweleko.',
        23: 'Ari, ma koe wa dong pei saraui om mairong, ap tamanda wasa o, me ri om ol insensued pa om.',
        24: 'Pwilikidi mas om mairong impan pei saraui, ap kola kadeke ri om ol, ap kodo kapwaiada om mairong.',
        25: 'Madang materoki ong me palian ong uk ni om iang i pon al o, pwe me palian ong uk ender pangalang uk ren saunkapung, a saunkapung pangalang uk ren papa o, o koe pan lokidokila nan imateng.',
        26: 'Melel I indai ong uk, koe sota pan ko sang wasa o, koe lao kapungala lua karos.',
        27: 'Komail rongadar, me a lokido: Koe der kamal!',
        28: 'A I indai ong komail, meamen ngingar li amen, pwen norok, nan a kamal ong i nan mongiong i.',
        29: 'O ma pali maun en mas om kamakar uk, waikada sang o kase sang uk, pwe a mau ong uk, kisan war om en ola, sang war om pon en lokidokila nan pweleko.',
        30: 'O ma pali maun en pa om kamakar uk, waika sang o kase sang uk, pwe a mau ong uk, kisan war om en ola, sang war om pon en lokidokila nan pweleko.',
        31: 'A pil lokido: Meamen me pan kasela a paud, i en ki ong i kisin likau en kamueit.',
        32: 'A I indai ong komail, meamen me pan kasela a paud, me so nenek nan a kin kamal eki i; a meamen, me paudeki me lokido kilar, nan i me kamal.',
        33: 'Komail pil rongadar, me a loki ong men kaua: Koe der kaula likam; a koe kapwaiada om kaula ong Kaun o!',
        34: 'I indai ong komail, der man kaula! Der kaukila nanlang, pwe mol en Kot;',
        35: 'Pil der sappa, pwe utipa; pil der Ierusalem, pweki kanim en Nanmarki lapalap.',
        36: 'Koe pil der kaukila mong om, pwe koe sota kak ong wiada pit en monga eu, en puetepuet de tontol.',
        37: 'Omail kasokasoi pena en: Ei ei; so, so; pwe me dauli mepukat, kin tapi sang ni me sued.',
        38: 'Komail rongadar, me a lokido: Por en mas en depukki por en mas; o ngi pot en depukki ngi pot.',
        39: 'A I indai ong komail, komail der palian me sued. A meamen pikir uk ni pali maun en likin sap om, pil ki ong i pali teio.',
        40: 'O meamen, me men wa uk ala ni kapung, pwen adia sang om sakit, en pil ki ong i om likau pup.',
        41: 'O ma meamen ngidingid kin uk, en iang i mail eu, koe en iang mail riau.',
        42: 'Kisakisai ong me kin ngidingid re om, o koe der saupei sang me poekipoeki re om!',
        43: 'Komail rongadar, me a lokidor: Koe en pok ong men imp om ap kailongki om imwintiti!',
        44: 'A I indai ong komail, pok ong omail imwintiti kan. o kapakap kin irail, me paki komail;',
        45: 'Pwe komail en sapwilim en Sam omail, me kotikot nanlang. Pwe a kin kapwareda sapwilim a katipin pon me sued o me mau kan, o kotin kamoredi katau pon me pung o me sapung kan.',
        46: 'Pwe ma komail pok ong, me kin pok ong komail, da me pan kating pa’mail? Saunopwei sota kin wia due met?',
        47: 'O ma komail ranamau ong ri omail akan, da me komail sikiki sang me tei kan? Men liki kan sota kin wia due met?',
        48: 'Komail ari en unsokela dueta Sam omail, me kotikot nanlang, a unsok.',
    },
    6: {
        1: 'KOMAIL kalaka, pwe komail der kisakis sansal mon aramas, pwe ren udial; pwe ede sota pwain omail ren Sam omail, me kotikot nanlang.',
        2: 'Ari, koe lao kisakis, ede peuk saui mo om, duen me malaun akan kin wia nan sinakoke kan o nani al akan, pwe ren indand ren aramas. Melel I indai ong komail, re aleer arail pwain.',
        3: 'A koe lao kisakis, der kasale ong pali maing om, me pali maun om kin wiada.',
        4: 'Pwe om kisakis en rir; a Sam om, me kin masani wasa rir, pan kotin katingi uk.',
        5: 'Koe lao wia kapakap, koe der ras ong me malaun akan, pwe re men kapakap nan sinakoke kan, o nani al akan, pwe ren sansal mon aramas. Melel I indai ong komail, re aleer arail pwain.',
        6: 'A koe lao wia kapakap, ko ong nan om pera, a koe lao ritingidier wanim o, ap kapakap ong Sam om, me kotikot wasa rir, a Sam om, me kin masani wasa rir, pan kotin katingi uk.',
        7: 'Komail lao kapakap, komail depa purepur ong lokaia mal, duen men liki kan, pwe re kiki ong, me re pan pwaikida ar lokaia toto.',
        8: 'Komail ari ender dueta irail, pwe Sam omail kotin mangi meakan, me mau ong komail, mon omail poeki re a.',
        9: 'A iet duen omail pan wia kapakap: Sam at, me kotikot nanlang. Mar omui en saraui.',
        10: 'Wei omui en pwaida. Kupur omui en wiaui sappa dueta nanlang.',
        11: 'Kotikido ran wet at tungol kaukaule.',
        12: 'Lapwa sang kit dip at, dueta kit me kin lapwada koros, me wia dipi ong kit.',
        13: 'Eder kaluang kit ren me katikatiamau kan, a nekid kit sang ni me sued akan,',
        14: 'Pwe ma komail pan makeki ong aramas dip ar akan, Sam omail nanlang pan pil makeki ong komail.',
        15: 'A ma komail sota pan makeki ong aramas dip ar akan, nan Sam omail sota pil pan makeki ong komail dip omail akan.',
        16: 'Komail lao kaisesol, eder mas en sang duen me malaun akan, pwe re kin kawukila mas arail, pwe aramas en kilang arail kaisesol. Melel I indai ong komail, re aleer arial pwain.',
        17: 'A koe lao kaisesol, usor mong om o opinok.',
        18: 'Pwe koe dor kasale ong aramas om kaisesol, a ong Sam om, mi kotikot wasa rir, a Sam om, me kin masani nan wasa rir, pan kotin katingi uk.',
        19: 'Komail der ki pena omail pai kan nin sappa, wasa man en mot o mir pan kawela ia, o men pirap kin weirada o pirapala.',
        20: 'A komail ki pena omail pai kan nanlang, wasa man en mot de mir sota pan kawela, o men pirap sota kin weirada de pirapala.',
        21: 'Pwe wasa om pai mia ia, iei wasa mongiong om kin pil mia ia.',
        22: 'Por en mas iei marain en pali war. Ari, ma mas om makelekel, war om karos pan dir eng marain;',
        23: 'A ma mas om me sued, war om karos pan dir en rotorot. A ma marain, me mi lol om, pan rotorot, daduen wan rotorot!',
        24: 'Sota amen me pan kak papa saumas riamen, pwe a pan kailongki amen, ap pok ong me teio, de a pan kasampwaleki amen, ap mamaleki me teio. Komail sota pan kak papa Kot o mamon.',
        25: 'I me I indaiki ong komail: Eder ngongongki ong maur omail, me komail pan kang o me komail pan nim, pil sota ong war omail, me komail pan likau kida. Pwe maur so kasampwal sang kisin manga, o pali war sang likau?',
        26: 'Kalelapok ong manpir pan lang; re sote, kin kamoredi, re soin kin dolung, re sota kin nak pena; ari so, Sam omail nanlang kotin kamakamanga irail; a ia duen, komail so kasampwal sang irail?',
        27: 'A is nan pung omail, ni a ngongki, me pan kak use pasang pein i ki tipong en pa eu?',
        28: 'O menda komail ngongki likau? Kalelapok ong kiop akan, me mi nan sap, duen ar kakairida. Re sota kin dodok o sota monkol pena.',
        29: 'A I indai ong komail: Nan Salomo ni a lingan karos sota a likau dueta apot irail.',
        30: 'Ari, ma iduen Kot kotin kapwataki dip, me mi nan sap, me kin mi ran wet, a lakap pan lokidokila nan kisiniai, dadue a sota pan kotin kalikauwi komail da, me poson tikitik?',
        31: 'I me komail der ngongongki moinda: Da me se pan kang? De da me se pan nim? De da me se pan likau kida?',
        32: 'Pwe mepukat men liki kan kin raparapaki; pwe Sam omail nanlang kotin mangi, me mepukat karos mau ong komail.',
        33: 'Rapaki mas wein Kot o a pung, a mepukat karos pan pouselang komail.',
        34: 'Eder ngongki ong lakap; pwe lakap pan ngongki ong pein i; a itar ong ran eu pein a sued.',
    },
    7: {
        1: 'DER kadeikada, pwe komail der pakadeikada.',
        2: 'Pwe duen kadeik, me komail kadeikekida aramas, iduen komail pan pakadeikada, o duen men song, me komail kin songki, iduen a pil pan song ong komail,',
        3: 'A menda koe kilikilang diper ni mas en ri om ol, a sota kan ataut o ni mas om?',
        4: 'De iaduen koe pan indang ri om ol: Aui mas, i pan ki sang diper ni mas om. A kilang, ataut apot mi ni pein mas om?',
        5: 'Malaun amen koe, ki sang mas ataut ni mas om, koe ap pan kak kilang, duen om pan kak ki sang diper ni mas en ri om ol,',
        6: 'Komail der ki ong kidi me saraui kot! O omail pai kan der kasedi ong mon pwik kan, pwe ren de tiak pasang, ap saupeido ngalis komail pasang.',
        7: 'Poeki, a komail pan tungole; rapaki, a komail pan diarada; letelet, a a pan ritida mo omail.',
        8: 'Pwe karos, me poekipoeki, kin tungole; o me kin raparapaki, kin diarada; o me kin letelet, nan a pan ritida mo a.',
        9: 'De is aramas nan pung omail, ma na putak pan poeki kisin prot, pan ki ong i takai eu?',
        10: 'De ma a poeki mam amen, pan ki ong i serpent amen?',
        11: 'Ari, ma komail me song sued, ap asa, ki ong noumail seri kan kisakis mau, melel kaualap Sam omail, me kotikot nanlang, pan kotiki ong, me poeki re a me mau kan.',
        12: 'Ari meakaros, me komail men, aramas en wiai ong komail, i me komail en wiai ong irail, pwe iei kapung o saukop akan,',
        13: 'Pedelong ong nan wanim tätik! Pwe wanim me walek o al me tälap, me kodilang mela, o irail me toto, me kin pedelong ong wasa o.',
        14: 'A wanim me watikitik, o al me tätik, me ko ong maur o irail me malaulau, me kin diarada.',
        15: 'Komail kalaka saukop likam akan, me kin pwara dong komail ni likau en sip, a lole irail song en kidi komad.',
        16: 'Komail pan asa kin irail ni arail wa. Pwe da, aramas pan kak dolung sang wain ni karer, de pik sang ni tuka kamadak?',
        17: 'Nan iduen tuka mau karos kin wa mau, a tuka sued kin wa sued.',
        18: 'Tuka mau sota kak wa sued, o tuka sued sota kak wa mau.',
        19: 'Ari tuka karos, me so wa mau pan paledi o lokidokila nuni iai.',
        20: 'Ari, komail pan asa kin irail ni arail wa.',
        21: 'Kaidin karos, me kin kasokasoi ong ia: Maing, Maing, pan pedelong ong nan wein nanlang, a me kin wiawia kupur en Sam ai, me kotikot nanlang.',
        22: 'Me toto pan kasoi ong ia ni ran o: Maing, Maing, kit so kokopadar ni mar omiu, o ni mar omui kausaki tewil akan, o ni mar omui wia kidar manaman toto?',
        23: 'I ap pan indai ong irail: I sota mail asa komail, kowei sang ia, komail me kin wiada me sued.',
        24: 'A meumen rongada ai padak pukut ap peiki ong, I pan karasai ong i ol lolokong amen, me kauada im a pon paip,',
        25: 'Katau lao moredi, o lakape pwilipwiledo, o ang me iripoki dong im o, a sota rongki pasang, pweki a kakauda pon paip.',
        26: 'O meamen rongada ai padak pukat, ap sota kapwaiada, nan a pan rasong ol pweipwei men, me kauada im a pon pik en oror.',
        27: 'Katau lao moredi o lapake pwilipwilido, o ang ma irepoki dong im o, a rongki pasang; o a rongk laud melel,',
        28: 'Kadekadeo Iesus lao kaimwisokela masan pukat, pokon o ap puriamuiki kaualap sapwilim a padak o.',
        29: 'Pwe a kotin kawewe ong irail ni manaman, a sota dueta arail saunkawewe kan.',
    },
    8: {
        1: 'A LAO kotido sang nin dol o, pokon kalaimun idauendo i.',
        2: 'A kilang, ol tuketuk amen ap kodo pongi i indada: Maing, ma re kotin kupura, re pan kak ong kamakele ia da.',
        3: 'I ari kotin kapawei lim a, sair i, masani: I men, koe en makelekel; ari, a tuketuk ap madang modi sang.',
        4: 'Iesus ap kotin masani ong i: Kalaka, koe de kaireki amen; a kola kasale ong samero pein uk, o kida mairong eu, me Moses masani, pwen kadede ong irail.',
        5: 'A lao kotilong ong nan Kapernaum, senturion amen apedong i poeki re a.',
        6: 'Indada: Maing, ai ladu wonon nan deu a somau kokon madak ap wairok kaualap.',
        7: 'Iesus ap kotin masani ong i: I pan kola kakelailada i.',
        8: 'Senturion sapeng potoan ong: Maing, i sowar ren kotilong ong nan im ai; a ren masani eta, ai ladu up pan kelailada,',
        9: 'Pwe aramas amen ngai, me mi pan mana en kaun akan, ap kaunda saunpei kai. A ma i pan indang amen: Kowei, a pan kola, o ong amen: Kodo, a pan kodo, o ong ai ladu: Wiada met, a pan wiada.',
        10: 'Iesus lao mangi mepukat, ap kotin puriamuiki, masani ong irail me idauendo: Melel I indai ong komail, song en poson wet I so diaradar, sota nan Israel.',
        11: 'A I indai ong komail, me toto pan kodo sang mas en lang, o kapin lang, iang Apraam, o Isaak, o Iakop ni tepel nan wein nanlang.',
        12: 'A me pweledan wei pan lokidokila nan rotorot liki, iei wasan maiei o teterok.',
        13: 'Iesus ap kotin masani ong Senturion o: U kowei, a pan wiaui ong uk duen om poson. A ladu o ap kelailadar ni auer ota.',
        14: 'Iesus lao kotilong ong nan im en Petrus, ap masani, me saulap a wonon somau karakar.',
        15: 'I ari kotin sair pa a, a karakar ap ko sang. I ari pauridar papa i.',
        16: 'A lao sautik penaer re wa dong i me toto, me tewil oko ti poa. I ari kotin kauseki sang ngen akan a masan o kakelada me somau kang karos.',
        17: 'Pwen pwaida, me lokido ren saukop Iesaia, me masani: A kotin ale ong pein i atail luet akan, o wa atail somau kan.',
        18: 'Iesus lao kotin masani aramas toto pokon dong i, ap kotin masani, ren kotela palio palilan sed o.',
        19: 'Saunkawewe men ap pwara do potoan ong i: Saunpadak i pan idedauen ir wasa karos re pan kotila ia.',
        20: 'Iesus kotin masani ong i: Poks akan por arail mia, o manpir en pan lang pas arail mia, a Nain aramas sota wasan kaulawei mong a.',
        21: 'O amen sang nan pung en sapwilim a tounpadak kan potoan ong i: Maing re kotin mueid ong ia en kola mas sarepedi ai papa.',
        22: 'A Iesus kotin masani ong i: Idauen ia do! Me melar akan en sarepedi pein ar melar akan.',
        23: 'A lao kotida pon sop o, sapwilim a tounpadak kan idauenla i.',
        24: 'A kilang, ap ongiongidar nan sed, iluk kan ari kadupaledi sop o, a i kotin saimokelar.',
        25: 'Sapwilim a tounpadak kan ap kai dong i, kaupada i, potoan ong: Maing, re kotin dore kit ala, kit pan mela!',
        26: 'A ap kotin masani ong irail: Komail me poson tikitik, da me komail masak ki? I ari kotin kipadar masani ong ang o sed, ap molelar kaualap.',
        27: 'Aramas akan puriamuiki indada: Daduen men et, me ang o sed kin peiki ong?',
        28: 'A lao kotin lei ong palio nan sap en men Kerkasin, ol riamen, me tewil oko ti poa, ap tu ong i; ira kodado sang nan sousou kai, me makar kaualap, o sota me kak weid wasa o.',
        29: 'A kilang, ira weriwer indada: Iesus Sapwilim en Kot, da me kit en wia re omui? Kom kotido kame kit mon ansau o leler?',
        30: 'A pwin pwik kalaimun mi kaila wei mangamanga sili.',
        31: 'Tewil oko ap poeki re a indada: Ma kom pan kause kit ala, ap mueid ong kit, en tilong nan pwin pwik o.',
        32: 'I ari kotin masani ong irail: U ko ong! Irail keredi sang, rap tilong nan pwin pwik o. A kilang, pwin pwik o tangdaui, tangedi ong wasa ukedi nan sed, irail ari mopelar nan pil o.',
        33: 'Silepa kan ap tangdaui tanglong ong kanim o kakaireki meakaros, duen me wiaui ong me tewil ti poa ko.',
        34: 'A kilang, toun kanim koiei sang pokon dong Iesus. Irail lao kilanger i, rap poeki, a en kotila sang sap arail.',
    },
    9: {
        1: 'I ARI kotida pon sop o, kotela pur ong sapwilim a kanim.',
        2: 'A kilang, re wa dong i me somau kokon madak, me wonon pon pet. Iesus lao kotin masani ar poson, ap masani ong me somau kokon madak: Nai, kaporopor mau, dip om akan me lapwadar.',
        3: 'A kilang, saunkawewe kai mongemongeloleki: Lap o kin lalaue.',
        4: 'A Iesus lao mangi arail lamelam, ap kotin, masani: Menda komail lamelam sued nan mongiong omail?',
        5: 'Pwe ia me mongai ren inda: Dip om akan lapwadar! De inda: Uda aluwei?',
        6: 'A pwe komail en asa, me Nain aramas me manaman ong lapwada dip nin sappa iei me a kotin masanieki ong me somau kokon madak: Uda, ale ki om ko ong deu om!',
        7: 'I ari udar, koieilar deu a.',
        8: 'Pokon lao kilanger mepukat, rap malamalauak kila kapinga Kot, me kotiki ong aramas manaman due met.',
        9: 'Iesus lao kotiwei sang wasa o, ap masani aramas amen, me ad a Matäus, me momod nan deun nopwei, ap kotin masani ong i: Idauen ia do! I ari uda idauenla i.',
        10: 'Kadekadeo a lao kaipokedi konot nan im o, kilang saunopwei o me dipan me toto iang Iesus o sapwilim a tounpadak kan konokonot.',
        11: 'Parisär akan lao kilanger met, ap indang sapwilim a tounpadak kan: Da me omail Saunpadak iangki saunopwei o me dipan akan konokonot?',
        12: 'Iesus lao mangi mepukat, ap kotin masani: Me kelail akan sota mau ong saunwini, pwe me somau eta.',
        13: 'A komail kola, padakki wewen kasoi pot et: I kin polauleki kadek a kaidin mairong isis. I kodon eker dong kalula me dipan akan, a kaidin me pung kan.',
        14: 'En Ioanes a tounpadak kan ap pwara dong re a potoan ong: Da me kit o Parisär akan kin kaisesol pan pak toto, a sapwilim omui tounpadak kang sota kin kaisesol?',
        15: 'Iesus ap kotin masani ong irail: Da, toun kamadip en kapapaud pan kak kamauk ni ansau ol kamot mi re’rail? A kadekadeo eu ran ol kamod pan peukawei sang irail, re ap pan kaisesol.',
        16: 'Sota amen me kin deipinaki likau kap likau maring, pwe me depin a pan teirok sang likau o, a por o pan laudela.',
        17: 'Pil sota amen me kin kodie ong wain kap nan ed maring, a ma ei ed akan pan ola, a wain pan wudokela, o ed akan pan ola. A re kin kodie ong wain kap nan ed kap, ira karos ap nekinek mau.',
        18: 'Ni a kotin masani ong irail mepukat, kilang saupeidi amen ap pedelong, poridi ong i potoan ong: Nai seripein apton melar, a ren kotido, pwil po a lim ar, a ap pan maureda.',
        19: 'Iesus ari kotida idauenla i, o sapwilim a tounpadak kan pil iang.',
        20: 'A kilang, li amen, me nta pwilipwil par ngaulriau, a kai ong pon palikia o sair imwin sapwilim a likau.',
        21: 'Pwe a lamelame: Ma i doke sapwilim a likau, i pan kelailada.',
        22: 'A Iesus kotin saupeila; a lao masani i, ap kotin masani: Seripein kaporopor mau, om poson me kakelail uk ada. A li o kelailadar ni auer ota.',
        23: 'A Iesus lao kotilong ong nan im en saupeidi o, ap masani saunkasang o moromorong en aramas akan,',
        24: 'Ap kotin masani: Kowei sang, pwe seripein en sota melar, pwe a mamair. Irail ap kaurureki i.',
        25: 'Aramas akan lao kokok sang, i ap kotilong ong, ale pa a, seripein ap paurida.',
        26: 'Mepukat ap lolok sili nan sap karos.',
        27: 'Iesus lao kotila sang wasa o, ol maskun riamen idauenla i, weriwer indada: Kupura kit, Komui sapwilim en Dawid!',
        28: 'A lao kotilong ong nan im o, me maskun ko ap ko dong i. Iesus ari masani ong ira: Koma kamelele, me I kak ong wiada met? Ira potoan ong: Ei Maing.',
        29: 'I ap kotin sair mas ara masani: Duen oma poson a pan wiaui ong koma.',
        30: 'Mas ara ari pad pasang. Iesus ap kotin kalik ira di masani: Kalaka, pwe meamen de asa!',
        31: 'A ira koieilar katiti sili ni sap karos.',
        32: 'Ira lao koieilar, kilang, irail ap wa dong i aramas amen, me lotong o tewil ti poa.',
        33: 'Tewil lao pakausa sang, me lotong o ap lokaia; pokon o ap malamalauak kila indada: Nan dueta met a saikenta wiauier nan Israel.',
        34: 'A Parisär indada: Nan saumas en tewil akan me a kausaki sang tewil akan.',
        35: 'Iesus ap kotin kakan sili nan kanim laud o me tikitik kan kawewe nan ar sinakoke kan o padapadaki rongamau en wei, o kotin kakelada song en somau o luet akan karos.',
        36: 'A lao masani pokon o, ap kotin kupuro kin irail, pwe irail soangiangalar o dupokalar dueta sip akan, me sota sile parail.',
        37: 'I ap kotin masani ong sapwilim a tounpadak kan: Nan melel rak me kalaimun, a men dodok me malaulau.',
        38: 'Komail ari poeki ren Kaun en rak, en kadarala toun dodok kan nan a rak.',
    },
    10: {
        1: 'A LAO kotin molipe penaer sapwilim a tounpadak ekriamen ap kotiki ong irail manaman, en poedi ngen saut akan, pwen kaus ir wei o kamauiala song en somau o luet karos.',
        2: 'A iet mar en wanporon ekriamen: Men mas Simon, me maraneki Petrus, o ri a Andreas, o Iakopus nain Sepedäus, o ri a Ioanes;',
        3: 'Pilipus o Partolomäus, Tomas o Matäus saunopwei men, Iakopus nain Alpäus, Lepäus, me pil adaneki Tadäus;',
        4: 'Simon men Kana o Iudas Iskariot men pangala i.',
        5: 'Ekriamen pukat, me Iesus kotin poronela, kotiki ong irail kusoned eu masani: Komail der weweid nani al en men liki kan o der pedelong ong nan kanim en Samaria.',
        6: 'A kola ren sip akan en saun Israel, me salongalar.',
        7: 'A ni omail kokola komail padapadak indada: Wein nan lang korendor.',
        8: 'Kakeada me somau kan, o kamaureda, me melar akan, kamakelekeleda, me tuketuk kan, o kause wei tewil akan; a duen komail aleer ni tiak en kisakis, iduen komail pan kisakis weita.',
        9: 'Komail der wewa kold, de silper, de mata nan omail ed akan.',
        10: 'Pil der ed en sailok, de sakit riau, de sut, de sokon, pwe toundodok me war ong kan a kisin manga.',
        11: 'A ma komail pan pedelong ong nan kanim laud de tikitik eu, raparapaki, ma meamen mi lole, me war ong; ari, komail pan mondi re a, lao komail pan ko wei sang.',
        12: 'A ma komail pan pedelong ong nan im o, komail pan ranamau ong tou a kan.',
        13: 'O ma re war ong, omail popol pan ko ong irail; a ma re sowar, omail popol pan pure dong komail.',
        14: 'A wasa kis meamen sota pan kasamo komail, de sota men rong omail padak, komail ari pedoi sang nan im o de kanim, ap sepede sang pwel ni nä omail.',
        15: 'Melel I indai ong komail, nan a pan mongai ong sap en Sodom o Komora ni ran en kadeik o sang kanim o.',
        16: 'Kilang I kadar komail la duete sip akan nan pung en kidi en wel; komail ari lolekong dueta serpent, a tiak mau dueta muroi.',
        17: 'Perki aramas, pwe re pan pangalang komail kapung kan, o re pan kame komail nan ar sinakoke kan.',
        18: 'O Komail pan wisike wong kaun o nanmarki kai pweki ngai, pwen kadede ong irail, o ong men liki kan.',
        19: 'Irail lao pangala komail, ede madamadaua duen tiak en omail pan lokaia; pwe a pan ko ong komail, ni auer o me komail pan inda.',
        20: 'Pwe kaidin komail, me lokaia, a Ngen en Sam omail, me pan kalokaia komail.',
        21: 'A pirien eu, amen pan pangala amen, pwen kamela, a sam na seri, a seri ko pan u ong ar papa o nono, o sauasa, pwe ira en kamela.',
        22: 'O komail pan tantat ren aramas karos pweki ad ai; a me pan dadaurata, lei imwi i me pan dorola.',
        23: 'A ma re pan kame komail nan eu kanim, komail ari tangala nan eu. Pwe melel I indai ong komail, komail sota pan kanikiala kanim en Israel karos, Nain aramas lao pwarador.',
        24: 'Tounpadak sota kin laude sang a saunpadak, de ladu laude sang a monsap.',
        25: 'A itar ong tounpadak, en paroki ong a saunpadak o ladu dueta a monsap. Ma re kaadaneki kaun en im o Peelsepup, nan melel kaualap, re pil pan wiai ong toun im akan dueta.',
        26: 'Komail ari der masak irail, pwe sota me rir kot, me so pan sansaleda, o me okiok, me so pan kadiarokad.',
        27: 'Me I indai ong komail nan rotorot, i me komail katiti nan marain; o me pan ko ong nan salong omail, i me komail pan kalok sili pon im akan.',
        28: 'Komail der masak irail, me kin kemela pali war, ap sota kak ong kamela pali ngen. A komail masak melel i, me kak ong kasopokela pali war o ngen nan pweleko.',
        29: 'Siok riamen sota kin netila ni denar eu? Ari so, sota amen ira pan pupedi nan pwel, ma sota pwilisang ren Sam omail.',
        30: 'Ari pit en mong’ omail karos me wadawad penaer.',
        31: 'Komail ari der masak, pwe komail me mau sang siok toto.',
        32: 'Meamen pan ponasa ia mon aramas, nan i me I pan ponasa ren Sam ai, me kotikot, nanlang.',
        33: 'A meamen ponsasa ia mon aramas, nan i me I pil pan ponsasa ren Sam ai, me kotikot nanlang.',
        34: 'Eder kiki ong, me I kodon kamuei maula sappa; kaidin muei mau, me I kokido, a kodlas pot.',
        35: 'Pwe I kodon kaliak toror pasang aramas ong sam a, o seripein ong in a, a li o ong en a paud a nono.',
        36: 'O pein toun im en aramas amen pan a imwintiti.',
        37: 'Me pok ong sam de in a lapa sang a pok ong ia, nan a sowar ia. O me pok ong na putak de seripein lapa sang a pok ong ia, nan a sowar ia.',
        38: 'A me so ale a lopu o idauen ia do, nan a sowar ia.',
        39: 'Me pan diar maur, i me pan katia sang, a me kasela maur a pweki ngai, i me pan diarada.',
        40: 'Meamen kasamo komail, kin kasamo ia, a me kin kasamo ia, nan a kin kasamo i, me kadar ia do.',
        41: 'Meamen kasamo saukop amen ni mar en saukop, pan ale pwain en saukop amen. Me kasamo pung amen ni mar en me pung amen pan ale pwain en me pung amen.',
        42: 'O meamen pan ki ong dal en pil lamelamur eu, pwe amen tikitik pukat en nim, ni mar en tounpadak amen, melel I indai ong komail, a sota pan katia sang pwain a.',
    },
    11: {
        1: 'KADEKADEO Iesus lao kaimwisokela a masan ong sapwilim a tounpadak ekriamen, ap kotila sang wasa o, pwen kaukawewe o padapadak nan ar kanim akan.',
        2: 'A Ioaneis lao ronger nan imateng wiawian Kristus, ap poronela a tounpadak kai.',
        3: 'Kalelapok re a: Ir me pan kotido, de sen auiaui amen?',
        4: 'Iesus kotin sapeng masani ong irail: Komail kowei kaireki Ioanes, me komail rong o kilang:',
        5: 'Me maskun akan kin kilang wasa, o me dangidang kan kin alu, o me tuketuk kan kin makeladar, o me salongepon kan kin rong wasa, o me melar akan kin maureda, o rongamau kin loloki ong me samama kan.',
        6: 'O meid pai, me sota pan makar kin ia.',
        7: 'Mepukat lao kokola, Iesus ap kotin tapiadar mamasani ong pokon o duen Ioanes: Da me komail koieila en kilang nan sap tan? Alek pot, me kin dueduälokki ang?',
        8: 'De da me komail koieila en kilang? Aramas amen nan likau muterok? Kilang, me kin likau kida likau muterok, kin mi nan im en nanmarki kan.',
        9: 'De da me komail koieila en kilang? Saukop amen? Ei I indai ong komail a laude sang saukop amen.',
        10: 'Pwe iei i, me intingidier: Kilang I kadarala mo’mui ai men kadar, me pan koko al mo’mui.',
        11: 'Melel I indai ong komail, sota me ipwidi sang ren li akan, me laude sang Ioanes saunpaptais. Ari so, me tikitik nan wein nanlang, iei me laude sang i.',
        12: 'A sang ni muein Ioanes saunpaptais kokodo lel met wein nanlang kokido eta manaman, ari me manaman akan kin koledi ong irail.',
        13: 'Pwe saukop karos o kapung kokopadar lao lel Ioanes.',
        14: 'O ma komail men duki ong, nan iei Elias, me pan kodo.',
        15: 'Me salong a mia, men rong, i en rong!',
        16: 'A da me I en karasai ong di wet? A ras ong seri kan, me kin momod nan wasan net akan o likelikwir ong kis arail,',
        17: 'Indada: Kit kasang ong komail, a komail, sota kakalek; kit kauleki ong komail kaul en mamauk, a komail sota sangesang.',
        18: 'Pwe Ioanes pwarado, ap sota kang o nim, a re kin inda: Nan tewil kin ti poa.',
        19: 'Nain aramas pwarado, mangamanga o nim, a re kin inda: Kilang, me kaped en manga o kamom sakau, kompoke pan saunopwei o me dipan akan, a lolekong o kin diarok kida na seri ko.',
        20: 'A kotin tapiada kidaueda kanim akan, me a wiai onger manaman to to, aki re sota kalula:',
        21: 'Suedi ong uk Korasin! Suedi ong uk Petsaida! Pwe ma manaman akan, me wiaui ong uk er, wiauier ong Tirus o Sidon, nan melel re pan pitipit kalula nan tuk en likau o nan pas.',
        22: 'A I indai ong komail, a pan mongai ong Tirus o Sidon ni ran en kadeik sang komail.',
        23: 'A koe Kapernaum, me paidar lel nanlang, pan pisikindi nan pweleko; pwe ma manaman akan, me wiaui ong uk er, wiauier ong Sodom, nan a pan mimieta lao lel ran wet.',
        24: 'A I indai ong komail, a pan mongai ong sap en Sodom ni ran mi kadeik sang koe.',
        25: 'Ni ansau ota Iesus kotin tapiadar masani: I kapinga komui Sam, Kaun pan lang o sappa, me komui okila mepukat sang me lolekong o koiok kan, ap kasale ong seri pwelel akan.',
        26: 'Ei Sam ai, pwe iduen me komui kupukupura.',
        27: 'Meakaros muei ong ia er sang ren Sam ai, o sota amen, me asa sapwilim a Ol, pwe Sam eta, o sota amen, me asa Sam, pwe sapwilim a Ol eta, o me sapwilim a Ol pan kasale ong.',
        28: 'Komail karos, me pangadar o toutoular kodo re i I pan kamoleilei komail la.',
        29: 'Ale ong komail ai iok, o padakki sang ia; pwe Ngai me opampap o karakarak melel, komail ari pan diarada kamol pan ngen omail.',
        30: 'Pwe ai iok me mangai, o katoutou pai me marara.',
    },
    12: {
        1: 'I ANSAU o Iesus kotila nan mat en korn ni ran en sapat, a sapwelim a tounpadak kan men mangadar, rap dolunga sang wan korn o kangkang.',
        2: 'Parisär lau kilanger mepwukat, rap patoan ong i: Masani, sapwilim omui tounpadak kan kin wiada, me sota pung, en wiaui ni ran en sapat.',
        3: 'A kotin masani ong irail: Komail sota doropwe, me Dawid wiadar ni a o iang akan men mangadar?',
        4: 'Duen a pedelong ong nan im en Kot o kangkang prot en kasansal, me sota pung, i o iang akan en kang, pwe samero akan eta.',
        5: 'De komail sota wadoker nan kapung o, duen samero akan ar kin kaupali ran en sapat nan im en kaudok ni ran en sapat, ap sota dip arail?',
        6: 'A I indai ong komail, i, me laude sang im en kaudok, mi wasa kis et.',
        7: 'A ma komail pan asa wewen kasoi pot et: I kin polauleki kadek a kaidin mairong isis, komail sota pan kadeikada me makelekel akan.',
        8: 'Pwe nain aramas pil udan Kaun en sapat.',
        9: 'A kotila sang wasa o, ap kotilong ong nan ar sinakoke.',
        10: 'A kilang, aramas amen mia, me pa a motorlar. Irail idok re a indada: Me pung, en kakelailada ni ran en sapat? Pwe ren kadipa i.',
        11: 'I ari kotin masani ong irail: Is aramas nan pung omail, me na sip amen mia, ma a pupedi ong nan por ni ran en sapat, a so pan poridi ong, kida sang?',
        12: 'A iaduen aramas amen sota kasampwal kaualap sang sip amen? I me aramas amen kak wia kida me mau ni ran en sapat.',
        13: 'I ap kotin masani ong aramas o: Kapa wei pa om! I ari kapa wei, ap maular dueta pali teio.',
        14: 'Parisär ap pedoi sang o kapukapung pena, duen ar pan kamatala i.',
        15: 'Iesus lao mangi met, ap kotila sang wasa o, a pokon kalaimun idauenla i; i ari kakelailadar irail karos.',
        16: 'O masani ong irail, ren der kalok sili i.',
        17: 'Pwen pwaida, me lokido ren saukop Iesaia, me masani:',
        18: 'Kilang, i ai ladu, me I piladar, o kompokepa i, me I kin polaule kida. I pan aude kin i Ngen i, o a pan kasale ong men liki kan duen kadeik o.',
        19: 'Nan a sota pan akamai de weriwer, o sota amen me pan rong ngil a pon al akan,',
        20: 'A sota pan katip pasang alek luet o, o a sota pan kakundi wik inkingkong o, lao a pan kaimwisokala kadeik o.',
        21: 'O men liki kan pan kaporoporeki mar a.',
        22: 'Me tewil ti poa men, me maskun o lotong ap wisike dong i; i ari kakelailada i, a me maskun o lotong ap lokaia o kilang wasa.',
        23: 'Aramas karos ap malamalauak kila indada: Kaidin i sapwilim en Dawid?',
        24: 'A Parisär akan lao rongadar, rap indada: Nan sota, me lap en kauseki wei tewil akan, Peelse pup eta, saumas en tewil akan.',
        25: 'I ari angi ar lamelam masani ong irail: Wei karos, ma tou a kan pan u pena nan pung ar, a pan ola, o ma toun kanim de toun im eu pan u pena nan pung ar, a sota pan pwaida.',
        26: 'O ma Satan pan kause wei Satan, a pan u ong pein i, a iaduen a wei pan kak pwaida?',
        27: 'Ma I kin kauseki wei Peelsepup tewil akan, a is me noumail seri kang kin kause kin irail? Irail ari pan omail saunkapung.',
        28: 'A ma I kausaki wei Ngen en Kot tewil akan, nan wein Kot lel ong komail er.',
        29: 'De iaduen, is me pan kak kolong ong nan im en me kelail amen, kulia sang a kapwa, ma a so saliedi mas me kelail o? A ap pan kak kulia sang a kapwa.',
        30: 'Meamen me sota iang ia, iei me palian ia; o me sota kin dolung penang ia, iei me kin kasapoka pasang.',
        31: 'I me Ngai indai ong komail, dip karos o lalaue pan kak lapwa sang aramas, a lalaue ong Ngen sota pan lapwa sang aramas.',
        32: 'O me pan lalaue Nain aramas, a pan lapwa sang i; a me pan lalaue Ngen saraui, a sota pan lapwa sang i, sota nan muei met pil sota nan muei kokodo.',
        33: 'Padukedi tuka mau pot, a wa pan mau; de padukedi tuka sued apot, a wa pan sued. Pwe tuka kin diarok kida wa.',
        34: 'Wan serpent komail, iaduen komail kak lokaia mau, pwe komail me sued? Pwe aua kin lokaia sang nan audepan mongiong o.',
        35: 'Aramas mau kin kida me mau sang nan pai mau en mongiong i, a aramas sued kin kida me sued sang nan pai sued en mongiong i.',
        36: 'A I indai ong komail, lokaia mal karos, me aramas inda, pan puk ong ir ni ran en kadeik o.',
        37: 'Pwe sang ni om kasokasoi koe pan kapung kila, o sang ni om kasokasoi koe pan pakadeikada.',
        38: 'Saunkawewe o Parisär kai ap sapeng i indada: Saunpadak, se men kilang kilel eu sang re omui',
        39: 'A i me kotin sapeng masani ong irail: Di sued o kamal o kin rapaki kilel eu, a sota kilel eu, me pan sansal ong irail, pwe kilel en saukop Iona eta.',
        40: 'Pwe duen Iona a mimi nan kaped en mam kalaimun amen ran silu o pong sili pong, iduen Nain aramas pan mimi nan mongiong en sappa ran silu o pong sili pong.',
        41: 'Ol en Niniwe kan pan u ong di wet ni kadeik lapalap o pan kadeikada, pwe re kalula ni ar rongadar padak en Iona, a kilang, me laude sang Iona mi met.',
        42: 'Li nanmarki en pali air amen pan u ong di wet ni kadeik lapalap o pan kadeikada; pwe a pwurado sang ni imwin sappa, pwen rong lolekong en Salomo. A kilang me laude sang Salomo mi met.',
        43: 'Ngen saut lao kowei sang ren aramas o, a kin tangatang sili nan sap tan akan, rapaki wasan kamol, a sota, me a diarada.',
        44: 'I ap kin inda: I pan purelong nan im ai, me i pedoi sanger. A lao puredo, a diar me a tan, kokok, o kapwater.',
        45: 'I ari mi koieila, ale ong i ngen isimen, me sued sang pein i; irail lao pedelong ong lole, rap kaukauson ia, a aramas pan sued sang mas. Iduen a pan wiaui ong di sued wet.',
        46: 'A ni a kotin masani ong pokon o mepukat, kilang, in a o ri a ol akan u liki, re men lokaia ong i.',
        47: 'Amen ap potoan ong i: Re kotin mangi, in ar o ri ar ol akan mimi liki o men lokaia ong ir.',
        48: 'A a kotin sapeng masani ong, me kaireki ong i: Is in ai o is ri ai ol akan?',
        49: 'Ap kotin kapawei lim a pon sapwilim a tounpadak kan masani: Kilang, in ai o ri ai ol pukat!',
        50: 'Pwe meamen, me kin wia kupur en Sam ai, me kotikot nanlang, nan i me ri ai ol, o ri ai li, o in ai.',
    },
    13: {
        1: 'NI ran ota Iesus kotila sang nan im o, ap kaipokedi pon oror.',
        2: 'A pokon kalaimun pokon dong i, i ari kotidang pon sop pot, kaipokedi, a pokon o udar pon oror o.',
        3: 'I ari karaseraseki ong me toto masani: Kilang, saunkamor o kolan kamorok.',
        4: 'Ni a kamokamorok, akai ap moredier ong pon kailan al, manpir ap pirido nam ir ala.',
        5: 'A akai moredier wasa takain, wasa pwel pedeped; ir ari pitipit wosadar pweki sota pwel lole.',
        6: 'A katipin lao dakaradar, re motoredier o mongelar, pweki sota kalau ar.',
        7: 'A akai moredier nan tuka teketek; a tuka teketek wosadar kasoka ir ala.',
        8: 'A akai moredier nan pwel mau o wadar: Akai pan me epuki, akai me woneisok, akai me sileisok.',
        9: 'Me salong a mia, men rong, i en rong!',
        10: 'Tounpadak kan ap pwarado potoan ong i: Da me re kotin kaukawewe ong irail ni karaseras akan?',
        11: 'A kotin sapeng masani ong irail: A muei ong komail er, en asa, me rir en wein nanlang, a ap sota muei ong mepukat.',
        12: 'Pwe me a mia, ekis pan ko ong, pwen aneki me laud; a me sota a mia, nan a pan katia sang, me mi re a.',
        13: 'I me I padaki ong irail ni karaseras. Pwe re kilang wasa, ap sota kin kilang, o rong wasa, ap sota kin rong, pwe re sota kin dedeki.',
        14: 'Nan irail kapung pan kokop en Iesaia, me masanier: Komail pan rongki salong omail, ap sota dedeki, o kilangki mas omail, ap sota weweki.',
        15: 'Pwe mongiong en aramas pukat kapitakailar, o salong arail ponlar, o re kamair pena mas arail. Pwe kadekadeo re de kilangki mas arail, o rongki salong arail, o lolokongki mongiong arail, o wukila, a I de kakel irail ada.',
        16: 'A mas omail meid pai, pwe re kilang wasa, o salong omail, pwe re rong wasa.',
        17: 'Pwe melel I indai ong komail, saukop o me pung akan me toto, me anane en kilang, me komail kin kilekilang, ap sota kilanger, o en rong, me komail kin rongerong, a re sota rongadar.',
        18: 'Komail ari rong karasepa wet duen saunkamorok:',
        19: 'Meamen rong masan duen wei o ap sota dedeki, me sued ap pwarado, katia sang, me kamoremoredier nan mongiong i, a iei i, me ale war akan pon kailan al o.',
        20: 'A me kamoremoredier wasa takain, iei i, me kin rongada masan o, ap pitipit peren kida ale;',
        21: 'A sota kalau a re a, pwe a lol masarang, pwe ansau apwal o kamekam lao pwaida pweki masan o, a ap madang makar kida.',
        22: 'A me kamoremoredi ong nan tuka teketek, iei i, me kin rongada masan o, a anan en pai en sappa o widing en dipisou kang kin kasokela masan o, ap so wa.',
        23: 'A me kamoremoredi nan pwel mau, iei i, me kin rongada masan o, ap dedeki o wada; akai kin pan me epuki, a akai me woneisok, a akai sileisok.',
        24: 'A kotiki ong irail er pil apot karaseras masani: Wein nanlang rasong aramas amen, me kamoredi war mau nan sap we.',
        25: 'A aramas lao mairelar, a imwintiti ap pwarado kamoredier dip nan pung en korn ap koieila.',
        26: 'A tuka lao wosadar o wadar, dip ap pil pwaradar.',
        27: 'Ladu en kaun pan im o kan ap pwara dong i potoan ong i: Maing, kaidin war mau, me kom kotin kamoredier nan sap omui? A iaduen dip, a ko sang ia?',
        28: 'A masani ong irail: Aramas mor sued amen me wiadar. Ladu kan ap potoan ong i: Kom kotin mauki, sen kola matiada sang?',
        29: 'A masani: Iermen, pwe komail der matia sang dip iangaki korn.',
        30: 'A karos pan mimieta lao ansaun rak; ni ansaun rak i pan indang men dolung kan: Ki pena mas dip akan, pira pena ni kap akan, pwe aramas en karongala, a korn ki pena nan ai im en nak.',
        31: 'A kotiki ong irail pil apot karaseras masani: Wein nanlang rasong wan tuka eu, me aramas amen ale, padukedi ong nan sap we,',
        32: 'Me tikitik sang war karos, a a lao wosada, a kalaimun sang dip akan, o wiala tuka laud apot, manpir en pan lang akan ap pokon pena o mimi nan ra a kan.',
        33: 'A pilapot karaseras me a kotin masani ong irail: Wein nanlang rasong kalep kis, me li amen ale okila nan kasak en plaua silu, karos lao mutala.',
        34: 'Mepukat karos Iesus kotin padapadaki ni karaseras ong pokon o, o sota, me a kotin padaki ong irail, ma sota ni karaseras.',
        35: 'Pwen pwaida me lokido ren saukop o, me masani: I pan ki pasang au ai, pwen karaseras o pan kasansaleda me rir akan sang ni tapin kaua.',
        36: 'A ap kotin kadar pasang pokon o, kotilong ong nan tanpas o. Sapwilim a tounpadak kan ap kai dong i potoan ong: Re kotin kawewe ong kit karasepan dip nan matual o.',
        37: 'A kotin sapeng masani: Me kamoredi war mau, iei Nain aramas.',
        38: 'Matuel iei sappa. War mau iei toun wei. Dip iei nain mesued.',
        39: 'Imwintiti, me kin kamor ir edi, iei tewil. Rak me kaimwisoke pan sappa. Saundolung pene iei tounlang kan.',
        40: 'A duen dip akan a kin usa sang rong kila kisiniai, iduen a pan wiaui ni imwin kaua.',
        41: 'Nain aramas pan kadarala na tounlang kan, o re pan ki sang nan wei men kamakar karos, o me kin wiawia me sued.',
        42: 'O re pan kasapok ir alang len kisiniai iei wasan mamaiei o teterok.',
        43: 'Me pung kan ap pan lingaling dueta katipin nan wein Sam arail. Me salong a mia, men rong, i en rong!',
        44: 'Wein nanlang rasong pai eu, me rir nan matuel, me aramas amen diaradar ap okila, o peren kida, koieila, netikilar karos, me a naineki, ap netiadar matuel o.',
        45: 'Wein nanlang pil rasong saunet amen, me raparapaki takai kasampwal kai.',
        46: 'A lao diaradar eu, me kasampwalia, ap koieila netikilar a dipisou karos, netiada i.',
        47: 'Wein nanlang pil rasong uk apot, me kin kadudi nan sed, pwen oro pena song karos.',
        48: 'A lao direla, re kin apiadado pon oror, ap mondi pena, deuk ong me mau akan nan dal akan, a me sued akan re kin kasela.',
        49: 'Nan iduen a pan wiaui ni imwin kaua: Tounlang kan pan koieila, katoror sang me sued akan me pung kan.',
        50: 'O kasapok ir alang len kisiniai, iei wasan maiei o teterok.',
        51: 'Iesus kotin masani ong irail: Komail weweki mepukat karos? Re potoan ong: Ei Maing.',
        52: 'A ap kotin masani ong irail: I me saunkawewe karos, me sukusukuleki wein nanlang me rasong kaun pan im eu, me kin kapwareda sang a pai me kap o me maring.',
        53: 'Kadekadeo Iesus lao kaimwisokela karaseras pukat, ap kotin koieila sang wasa o.',
        54: 'A koti dong udan sap we kawewe ong irail nan ar sinakoke. Irail ari puriamui kila indada: Lolekong en Ol men et o a manaman akan ko sang ia?',
        55: 'Kaidin i nain kapenta? In a sota adaneki Maria? O ri a ol akan Iakop, o Iosep, o Simon, o Iudas?',
        56: 'O ri a li akan, kaidin irail karos mi re atail? Ari, ia wasa mepukat ko sang ia?',
        57: 'O irail makar kin i. A Iesus kotin masani ong irail: Sota wasa me saukop so waui ia, nan sap we ota o ren sau i ko.',
        58: 'I ari sota wiadar manaman toto wasa o pweki ar soposon.',
    },
    14: {
        1: 'I DOKAN nanmarki Erodes ronger duen wiawia en Iesus.',
        2: 'Ap masani ong sapwilim a ladu kan: Nan i Ioanes saunpaptais, a mauredar sang ren me melar akan, i me a wia kida manaman pukat.',
        3: 'Pwe Erodes koledier Ioanes o saliedier ong nan imateng pweki Erodias en ri a Pilip a paud.',
        4: 'Pwe Ioanes me masani ong i: A sota muei ong komui en ale i.',
        5: 'O a men kamela i, a a masak aramas akan, pwe re wiakin i saukop amen.',
        6: 'A en Erodes a ran en ipwidi wiauier, nain Erodias seripein ap kakalek mo’rail, i me Erodes peren kidar.',
        7: 'I ari inauki ong i, me a pan ki ong i, meakaros, me a pan poeki, ap kotin kaula,',
        8: 'A lao pwili sang in a, ap potoan ong: Kotiki dong ia mongan Ioanes saunpaptais pon dal wet.',
        9: 'Nanmarki ap kupur suedelar; a pweki a kaula o pweki irail, me iang i kot ni tepel o, a masani ren ki ong i.',
        10: 'I ari poronelar en lepuk sang mangan Ioanes nan imateng.',
        11: 'Monga ap wisikedor pon dal eu, ap pangalang seripein o, i ap wala ren in a.',
        12: 'A tounpadak kan ap pwarador, ale kalep a, sarepedier, rap kola kaireki Iesus.',
        13: 'Iesus lao mangi mepukat, ap kotin iangalar sop pot, kotilang sap tan eu. Pokon lao rongadar, rap idauenla i sapasapal sang nan kanim akan.',
        14: 'A lao kotila sang wasa o, ap kotin masani pokon kalaimun, ap kupuro kin ir ala, o kotin kakelada, me somau re’rail.',
        15: 'A lao sautik penaer sapwilim a tounpadak kan kaidong i potoan ong: Sap tan eu met o ansau daulier; re kotin kadar pasang pokon o, pwe ren kola nan kanim akan, netiada kang ar manga.',
        16: 'A Iesus kotin masani ong irail: Sota kare pan ar kola, komail pan katungole irail.',
        17: 'A irail potoan ong i: Sota at tungol met, lopon en prot eta limau o mam eta riamen.',
        18: 'A a kotin masani: Wa dong ia!',
        19: 'A ap kotin masani, pokon en mondi nan ra, ap kotikida lopon en prot limau o mam riamen, ap kotin masanda nanlang, laolaoki pilitiki pasang o kotiki ong tounpadak kan lopon en prot oko a tounpadak kan ap nek ong pokon o.',
        20: 'Irail karos ari manga o medier; rap deuk pena kopou en maremor eisok riau luan kamadip o.',
        21: 'A irail, me mangaer, me ol limekid a li o seri kan sota iang wadawader.',
        22: 'A ap kotin pain tounpadak kan, ren keredi pon sop pot, pwe ren madangwei mo a lel palio, lao a pan kotin kadar pasang pokon o.',
        23: 'A lao kotin kadar pasang ponkon o, ap kotin kelepelar pon nana eu, pwen laolao. A lao, sautik penaer i eta, me kotikot wasa o.',
        24: 'A sop o mi ni ailepan sed o lusiluseki iluk kan pwe ang udo sang moa.',
        25: 'A kadekadeo nan lukepan pong Iesus ap kotikot ko dong irail pon sed o.',
        26: 'A tounpadak kan lao kilanger i kotikot sili pon sed o, ap masapwekadar indada: Ani amen! Irail ap weriwer pweki ar masak.',
        27: 'A Iesus kotin madang kasoi ong irail masani: Kaporopor mau, pwe Ngai met, der masak!',
        28: 'A Petrus sapeng i patoan ong: Maing, ma ir, re kotin masan dong ia, i en kowei re ir pon pil o.',
        29: 'A ap kotin masani: Ukedo! Petrus ap keredier sang nan sop o, weweid pon pil o, pwen kola ren Iesus.',
        30: 'A lau kilanger ang ma, ap masapwekadar, a ni a pan kirila, a weriwer indada: Maing kupwura ia!',
        31: 'Iesus kotin madang kapawei lim a koledi i, masani ong i: O koe meid poson tikitik, da me koe so posonki?',
        32: 'Ira lao kotidar pon sop o ang ap moledier.',
        33: 'A toun sop o ap kaiong i, poridier potoan ong: Melel ir me Sapwilim en Kot!',
        34: 'Irail lao kotin kotela, rap kotilang sap Kenesaret.',
        35: 'Toun sap o lao asa i, rap kadar sili wasa karos, o re wa dong i me somau kan karos,',
        36: 'O poeki re a, ren potoan sair ta imwin sapwilim a likau. A karos, me sair i kelailadar melel.',
    },
    15: {
        1: 'PARISÄR o saunkawewe kan ap ko dong i sang Ierusalem, kalelapok re a:',
        2: 'Menda sapwilim omui tounpadak kan tiakedi padok en kaua ko? Pwe re sota kin omiom ni ar pan kang prot.',
        3: 'A i kotin sapeng masani ong irail: Menda komail pil tiakedi kusoned en Kot pweki omailpadok kan?',
        4: 'Pwe Kot kotin kusonedadar masanier: Kakaki sam om o in om, o meamen lalaue sam a de in a, i en kamela.',
        5: 'A komail kin inda: Meamen indang sam a o in a: Korpan, iet wewe: Mairong eu, me koe men aneki sang ia; komail inda, dene sota dip a; i ari sota pan kakaki sam a o in a.',
        6: 'Iduen omail tiakedi kusoned en Kot pweki omail padok kan.',
        7: 'Malaun akan komail, nan melel, me Iesaia kokopadar iran komail, ni a masani:',
        8: 'Aramas pukat kin kaka kin ia au arail, a mongiong arail me doo sang ia;',
        9: 'Ari, me mal ar kaudok ia, pwe kusoned en aramas eta, me re kin kaukawewe.',
        10: 'I ari molipe pena aramas akan masani ong irail: Rong o weweki!',
        11: 'Kaidin me kin ko ong nan aua kin kasaminela aramas, a me kin ko sang nan aua, i me kin kasaminela aramas.',
        12: 'Tounpadak kan ap kodo, potoan ong i: Re kotin mangi, me Parisär akan makar kida ni ar rongadar masan o?',
        13: 'A kotin sapeng masani: Tuka karos, me kaidin Sam ai nanlang, padukedier, pan weiweida.',
        14: 'Puei sang irail; irail me maskun, ap kalua me maskun akan. A ma me maskun amen pan kalua me maskun, nan ira karos pan pupedi ong nan por o.',
        15: 'Petrus ap sapeng potoan ong i: Re kotin kawewe ong kit karaseras pot et.',
        16: 'I ari kotin masani: Komail pil sota lolekong?',
        17: 'Komail saikenta weweki, meakaros, me kin ko ong nan aua kin kodilong ong nan kaped o ap kin kasapokela?',
        18: 'A me kin ko sang nan aua, kin tapida sang nan mongiong, o i me kin kasaminela aramas.',
        19: 'Pwe sang nan mongiong o lamelam sued kin tapi sang ia: Kamela aramas, o kamal, o nenek, o pirap, o kadede likam, o lalaue.',
        20: 'Song pukat, me kin kasaminela aramas. A so omiom ap manga sota kin kasaminela aramas.',
        21: 'Iesus ap kotila sang wasa o, kotilang wein Tirus o Sidon.',
        22: 'A kilang, li en Kanaan amen, me kodo sang wasa o, likelikwir ong i, potoan ong: Kupura ia! Maing, ir me sapwilim en Dawid! Nai sereipein waiwairokki tewil.',
        23: 'A a sota kotin sapeng i meakot. Sapwilim a tounpadak kan ap kai dong i poeki re a potoan ong: Re kotin kadarala i, pwe a kin likelikwir dong kitail.',
        24: 'A kotin sapeng masani: Sota me I pakadara dong, pwin sip en saun Israel eta, me salongalar.',
        25: 'A a kodo, poridi ong i potoan ong: Maing, re kotin kupura ia!',
        26: 'A kotin sapeng masani: A sota mau, en ale en seri ar tungol prot ap kasedi ong ren kisin kidi kan.',
        27: 'A potoan ong: Melel Maing, ari so, kisin kidi kan kin namenam maremor akan, me kin pupedi sang ni tepel en ar saumas.',
        28: 'Iesus ap kotin sapeng masani ong i: O li, om poson mo laud! A pan wiaui ong uk duen me koe inong iong. Na seripein ap kelailadar ni auer ota.',
        29: 'Iesus ari kotila sang wasa o, koti dong liman sed en Kaliläa, a lao kotida pon dol eu ap kaipokedi wasa o.',
        30: 'O pokon kalaimun pokon dong i, me wado me dangidang kai, o me maskun, o me lotong, o me sikilikil, o song toto, ap pwilikidi ni aluwilua. A ap kotin kakelail ir ada.',
        31: 'Pokon o ap puriamuiki ni ar kilang, me lotong akan lokolokaia, o me sikilikil akan kelailadar, o me dangidang kan alialu, o me maskun akan kilang wasa; rap kapinga Kot en Israel.',
        32: 'Iesus lao molipe pena sapwilim a tounpadak kan a kotin masani: I ap pokela pokon en, pwe re mi re i ran silu ap sota kan ar manga, a I sota pan kadar ir ala ni ar sota mangaer, pwe ren der dupokala pon al o.',
        33: 'Sapwilim a tounpadak kan ap potoan ong i: Se pan kisang ia prot toto, men kamedela pokon et nan sap tan wet?',
        34: 'Iesus kotin masani ong irail: Lopon en prot me depa mi re omail? Irail potoan ong: Me isu o kisin mam kis.',
        35: 'I ari kotin masani ong pokon o, en mondi ong nan pwel o,',
        36: 'Ap kotikidar lopon en prot isu o kisin mam akai, laolaoki, pwilitiki pasang o kotiki ong sapwilim a tounpadak kan, a tounpadak kan ap nek ong pokon o.',
        37: 'Irail karos ari mangaer, o medier; irail ap deuk pena kopou isu luan kamadip o.',
        38: 'A irail, me mangaer, me ol pakid, a li o seri kan sota iang wadawader.',
        39: 'A lao kotin kadar pasang pokon o, a kotilang pon sop pot, koti dong impan Maktala.',
    },
    16: {
        1: 'PARISÄR o Sadusär akan ap ko do, kasongesong i o poeki i kilel eu sang nanlang.',
        2: 'A ap kotin sapeng masani ong irail: A lao sautiker komail kin inda: Lakap a pan ran kaselel eu, pwe lang me waitata.',
        3: 'A ni mansang: A pan katau, pwe lang me waitata o rotorot. Komail kak ong kasauiada mom en lang, a komail sota kak kasauiada kilel en ansau.',
        4: 'Di sued o kamal o kin ngongki kilel eu, a sota kilel eu, me pan sansal ong irail, pwe kilel en Iona eta. I ari kotin muei sang irail o koti wei.',
        5: 'Sapwilim a tounpadak kan lao kotela lel palio, ap sota arail prot, pwe re monokelar.',
        6: 'A Iesus kotin masani ong irail: Kalaka o pereki kalep en Parisär o Sadusär akan!',
        7: 'Irail ari kasokasoi nan pung arail indada: Nan pweki sota atail prot, me se wado.',
        8: 'Iesus lao mangi mepukat, ap kotin masani: Komail meid soposon, menda komail kasokasoi nan pung omail, iran omail sota wado prot oko?',
        9: 'Komail saikenta dedekila o komail sota tamanda lopon en prot limau ren aramas limekid o kopou depa, me komail deuk penaer?',
        10: 'Pil so lopon prot isu ren aramas pakid, o kopou depa, me komail deuk penaer?',
        11: 'Daduen, komail so lolekongki, me kaidin kisin manga, me i kasokasoi; pwe komail en pereki kalep en Parisär o Sadusär akan,',
        12: 'Irail ap weweki, me a kaidin masanier, me ren kalaka kalep en prot, pwe ren kalaka padak en Parisär o Sadusär.',
        13: 'Iesus lao koti dong wein Säsarea Pilipi, ap kotin kainoma ren sapwilim a tounpadak kan masani: Da me aramas kin inda, is me ngai, Nain aramas?',
        14: 'Irail potoan ong: Akai: Ioanes saunpaptais, a akai: Elias, o pil akai: Ieremias de amen ren saukop oko.',
        15: 'Ap kotin masani ong irail: A komail, is me komail kin inda me nai?',
        16: 'Simon Petrus ap sapeng potoan ong: Ir me Kristus, Sapwilim en Kot ieias!',
        17: 'Iesus ap kotin sapeng masani ong i: Koe meid pai Simon nain Iona, pwe kaidin uduk o nta, me kasale ong uk met, pwe Sam ai, me kotikot nanlang,',
        18: 'A I pil indai ong uk, koe Petrus, a I pan kauada pon paip wet ai momodisou a wanim en pweleko kan sota pan kak kawela i.',
        19: 'I pan ki ong uk kapiri pan wein nanlang kan. A meakot koe pan saliedi nin sappa, pan salidi nanlang; o meakot, koe pan lapwada nin sappa, pan lapwada nanlang.',
        20: 'A ap kotin masani ong sapwilim a tounpadak kan, me ren der indang meamen, me i me Kristus.',
        21: 'I ansau me Iesus kotin tapiadar kasale ong sapwilim a tounpadak kan, me a pan kotilang Ierusalem o kalokolok laud ren saumas akan, o ren samero lapalap akan, o ren saunkawewe kan, o me a pan kalokolok toto o kamela o ni ran kasilu a pan maureda,',
        22: 'Petrus ap ukadar i, kapukapung i indada: Maing re kotin kupura pein ir, mepukat sota pan pwai ong ir!',
        23: 'A ap kotin saupeido masani ong Petrus: Kola muri Satan! Koe men kamakar ong ia, pwe om lamelam kaidin en Kot, a en aramas,',
        24: 'Iesus ap kotin masani ong sapwilim a tounpadak kan: Meamen pan idauen ia en tounmeteki pein i, ap wada a lopu, idauen ia.',
        25: 'Pwe meamen dorela maur a, pan pupe sang, a meamen kasela maur a pwreki ngai, i me pan diarada.',
        26: 'Pwe da kadepa ong aramas o, ma a aneki sappa pon, ap kasela maur a? De da me aramas pan kak kida, pwen kasapaledo maur a?',
        27: 'Pwe Nain aramas pan kokido lingan en Sam a, o sapwilim a tounlang kan pan iang i; i ari pan pwain ong aramas akan duen ar wiawia kan.',
        28: 'Melel I indai ong komail, akai me iang mimi met, me sota pan mela, irail lao kilang Nain aramas a kodo nan a wei.',
    },
    17: {
        1: 'MURIN pong wonu pong Iesus ap kotin ukadar Petrus, o Iakopus, o ri a Ioanes kalua ir dalang pon nana ileila eu kalapuk.',
        2: 'I ari kotin linganla mo’rail silang i lingaling dueta katipin, o sapwilim a likau o puetpuet eta marain eu.',
        3: 'A kilang, Moses o Elias pwara dong ir, kasokasoi ong i.',
        4: 'Petrus ap sapeng potoan ong Iesus: Maing, meid mau atail kotikot met. Ma re kotin mauki se pan kauada kisin im sili kis: Tanpas ar, o eu sapwilim en Moses, o eu sapwilim en Elias.',
        5: 'Ni a kasokasoidar, kilang, pali en dapok pali ap kadupal irail edi; o kilang, ngil eu peidido sang nan dapok o, me masani: Iet nai Ol kompok, me I kin polaule kida! Komail ron i!',
        6: 'Tounpadak kan lao rongadar met, rap pupedier pon mas arail, masapwekadar kaualap.',
        7: 'Iesus ap kotido, sair ir, masani: Uda, der masak!',
        8: 'Irail lao saradar, sota amen, me re kilanger, pwe Iesus eta.',
        9: 'Ari, ni arail kotikot kodido sang ni nana o, Iesus ap kotin masani ong irail masani: Komail depa indai ong meamen duen kasansal o, Nain aramas lao mauredar sang ren me melar akan.',
        10: 'Sapwilim a tounpadak kan kalelapok re a indada: Da me saunkawewe kan kin indinda, dene Elias pan kotido mas?',
        11: 'A kotin sapeng masani ong irail: Nan melel, Elias pan pwarado mas kapungala karos.',
        12: 'A ngai indai ong komail, Elias me pwaradoer, a re sasa i, pwe irail wiai ong i meakan, me re men wiada. Iduen Nain aramas pil pan kamekam re’rail.',
        13: 'Tounpadak kan ap asadar, me a kotin masani ong irail duen Ioanes saunpaptais o.',
        14: 'Irail lao lel dong pokon o, aramas amen poto dong i kelepuki mo a sakaradar:',
        15: 'Maing kupura nai ol o, pwe a pweipwei o madak kaualap, pwe pan pak toto a kin pupedi nan iai o nan pil,',
        16: 'Ngai ari wa dong i ren sapwilim ar tounpadak kan, a irail sota kak kakelada i.',
        17: 'Iesus ap kotin sapeng masani: Di wet meid soposon o katiwo. Ia arain ai pan mi re omail? Ia arain ai pan kokoa komail? Wa dong ia!',
        18: 'Iesus ap kotin kidaua i, tewil ari kodi sang lole; putak o ap kelailadar ni auer ota.',
        19: 'A tounpadak kan ap kelep poto dong Iesus potoan ong: Da me kit so kak kauseki wei sang i?',
        20: 'A ap kotin masani ong irail: Aki omail soposon. Pwe melel I indai ong komail, ma omail poson pan laude ong wan katiring, komail pan kak indang nana wet: Koda sang wasa en, kola monen! I ap pan kola, sota me sota pan kak pa omail.',
        21: 'Song wet sota kin koki sang meakot, kapakap o kaisesol eta.',
        22: 'A ni ar kotikot sili nan wein Kaliläa, Iesus kotin masani ong irail: Nain aramas pan pangalang nan pa en aramas.',
        23: 'Irail pan kamela i, a ni ran kasilu a pan maureda. Irail ari mamauk kaualap.',
        24: 'Irail lao kotilon ong nan Kapernaum, saunopwei kai ap ko dong Petrus indang i: Omail Saunpadak sota kin iang nopwei?',
        25: 'A masanier: Ei. A lao pedelong ong nan im o, Iesus ap kotin madang masani: Simon, da me koe lamelame, nanmarki en sappa kin ale taksis de nopwei sang ren is? Sang ren nairail seri de sang men liki kan?',
        26: 'Petrus potoan ong i: Sang ren men liki kan. Iesus kotin masani ong i: Ari, seri kan me saladok.',
        27: 'Ari so, pwe kitail der kamakar irail ada, kola ni oror kasedi kas, a mam men mas, me pan lodi, apiada, kasara pasang au a, koe pan diar lepen moni lep; i me koe pan ale o kida ai o noum.',
    },
    18: {
        1: 'NI auer ota tounpadak kan poto dong Iesus potoan ong: Iaduen is me pan lapalap nan wein nanlang?',
        2: 'Iesus lao kotin molipeido kisin seri amen, ap kotin kotiki ong nan pung arail,',
        3: 'Masani: Melel I indai ong komail, ma komail sota pan wukila, wiala song en kisin seri, komail sota pan kak ko ong nan wein nanlang.',
        4: 'Ari, meamen pan kasapwiledi pein i, dueta kisin seri men et, i me pan lapalap nan wein nanlang.',
        5: 'O ma amen apwali kisin seri men due met ni ad ai, i me kin apwali ia.',
        6: 'A meamen me pan kamakar amen ir, me tikitik, me poson ia, a mau ong, takai en plaua eu en sali ong tapin wor a, ap kamopela nan madau wasa me lol.',
        7: 'Suedi ong sappa pweki a men kamakar akan, Ari so, men kamakar akan udan mia; suedi ong aramas o, me men kamakar pan tapi sang ia.',
        8: 'A ma apali en pa om de apali en nä om pan kamakar uk, lepuke sang, o kase sang uk, pwe a mau ong uk ko ong maur ni om dangidang de sikilikil, sang om pa de nä pokon mia, ap ko ong kisiniai soutuk.',
        9: 'O ma apali en mas om pan kamakar uk, waikada sang o kase sang uk, pwe a mau ong uk, ko ong maur ni om mas pali, sang mas om pokon mia ap lokidokila nan iai en pweleko.',
        10: 'Kalaka, pwe komail der mamaleki amen tikitik pukat; pwe I indai ong komail, me arail tounlang kan, me mi nanlang, kin ariri Sam ai, me kotikot nanlang.',
        11: 'Pwe Nain aramas kodon dorela, me salongalar akan.',
        12: 'Da me komail lamelame, ma aramas amen, naineki sip epuki, a amen irail pan salongala, a so pan pwilikidi duekduamen pon nana, ap kola raparapaki me salongala?',
        13: 'A ma a pan diar, melel I indai ong komail, a pan peren kida, me men en sang duekduamen, me sota salongalar.',
        14: 'Iduen Sam omail, me kotikot nanlang, sota kotin men, amen kisin seri pukat en salongala.',
        15: 'A ma ri om ol wia dip ong uk, en kelep kila i, kapung ong i dip a; ma a pan rong uk, nan koe kasapaledo ri om.',
        16: 'A ma a sota pan rong uk, ap ukada amen de riamen, pwe meakaros en mi ren saunkadede riamen de silimen.',
        17: 'A ma a kang rong irail, ap kaireki momodisou, a ma a pil kang rong momodisou, ap wia kin i men liki o saunopwei men.',
        18: 'Melel I indai ong komail, me komail pan saliedi nin sappa, pan salidi nanlang, o me komail pan lapwada nin sappa, pan lapwada nanlang.',
        19: 'I pil indai ong komail, ma riamen nin sappa pan minimin pene ni meakot, me re men poeki, a pan pwai ong ira sang Sam ai, me kotikot nanlang.',
        20: 'Pwe wasa kis, me riamen de silimen pokon pena ni ad ai, i wasa I kin mi nan pung arail.',
        21: 'Petrus ap kai dong i potoan ong: Maing, pan pak depa i en makeki ong ri ai ol o, me wia dip ong ia? A itar ma a pan me isepak?',
        22: 'Iesus kotin masani ong i: I indai ong uk, kaidin isepak eta, a pan pak isu wad iseisok.',
        23: 'I me wein nanlang rasong nanmarki amen, me pan kapukapung na ladu kan.',
        24: 'A ni a tapiada kapukapung, amen ap wisike dong i, me pwaipwandeki talent nen.',
        25: 'A ni sota a men pwain, a monsap ap masanier, me a pan netila, o a paud, o na seri kan, o karos, me a aneki, pwen pwainda.',
        26: 'A ladu o ap poridi mo a pongi, potoan ong: Maing kom kotin kanongama ong ia, i pan pwain ong komui karos.',
        27: 'A monsap en ladu o ap pokela, ap lapwada o makeki ong i a pwaipwand.',
        28: 'A ladu ota ap koieila, diaradar kis a ladu amen, me pwaipwand ong i denar epuki; i ari koledi i, padik pena tapin wor a indada: Kapungala, ma om pwaipwand mia.',
        29: 'Ladu ap poridi mo a, poeki indada: Kom kotin kanongama ong ia, i pan pwain ong komui.',
        30: 'A a kang, ap koieila, kasedi ong nan imateng lao a kapungala a pwaipwand.',
        31: 'A kis a ladu kan lao kilanger me wiauier, rap mauk kaualap, koieila kaireki arail monsap karos, me wiauier.',
        32: 'A monsap ap ekere dong i, masani ong i: Koe meid ladu sued amen! I make ki ong uk er om pwaipwand karos pweki om poeki re i.',
        33: 'Menda koe sota kadek ong ri om ladu, duen i kin kadek ong uk er?',
        34: 'A monsap ap makar kidar o pangalang i ren saun kalokolok lao a kapungalar a pwaipwand karusia.',
        35: 'Iduen Sam ai nanlang, pan pil wia ong komail, ma komail sota pan makeki sang nan mongiong omail ong ri omail.',
    },
    19: {
        1: 'KADEKADEO Iesus lao kaimwisokela padak pukat, ap kotila sang Kaliläa, koti dong wein Iudäa palilan Iordan.',
        2: 'O pokon kalaimun idauendo i. I ari kotin kakelail ir adar wasa o.',
        3: 'Parisär akai ap kodo kasongesong i indada: Me pung, ol en kasela a paud pweki okotme?',
        4: 'A ap kotin sapeng masani: Komail sota doropwe, me i, me wia ir adar ni tapio, a kotin wiadar ol o li?',
        5: 'A ap kotin masani: I me aramas amen pan pweidedi sam a in a pat ong eta a paud; ira ari pan udukala eu;',
        6: 'Ira ari solar riamen pwe uduk eu. Ari, me Kot kotin kapad penaer, aramas depa kamueit pasang.',
        7: 'Irail ap indai ong i: A da me Moses masaniki, kisin likau en kamueit en koda, ol ap pan muei sang a paud?',
        8: 'A kotin masani ong irail: Moses mueid ong komail er, en kasela omail paud akan pweki mongiong omail kapitakailar. A sang ni tapi o a sota kin due.',
        9: 'A ngai indai ong komail: meamen kasela a paud, ma sota pweki nenek, ap paudekida amen; nan a kamal, o me pan paudeki, me lokidokilar o, a kin kamal.',
        10: 'Sapwilim a tounpadak kan ap potoan ong i: Ma iduen kusoned, me ol o en kapwaiadang a paud, a sota mau ong papaud.',
        11: 'A ap kotin masani ong ir: Kaidin karos, me pan kak weweki padak pot et, irail eta, me a muei ong er.',
        12: 'Pwe akai mia, me udan sota unsok, a akai, me aramas ki sanger, a pil akai, me wia kapwat pweki wein nanlang. Meamen kak ong weweki, i en weweki.',
        13: 'Kisin seri kai ap wisike dong i, pwen pwil po’rail lim a kan o laolaoki, a tounpadak kan kapoui irail.',
        14: 'A Iesus kotin masani: Mueid ong kisin seri kan, en ko dong ia. Der kalik irail edi! Pwe iei song en me udan wein nanlang.',
        15: 'I ari kotikida po’rail lim a kan, ap kotila sang wasa o.',
        16: 'O kilang, amen poto dong i potoan ong: Saunpadak da me mau kot, i en wiada, pwe i en aneki maur soutuk?',
        17: 'A ap kotin masani ong i: Menda koe idok re i duen me mau? Pwe amen ta me mau. A ma koe men ko ong maur, dadaurata kusoned akan!',
        18: 'A ap potoan ong: Kusoned da? A Iesus kotin masani, iet akan: Koe der kamela aramas; Koe der kamal; Koe der pirap; Koe der kadede likam;',
        19: 'Kakaki sam om o in om; o pok ong men imp om dueta ong pein uk.',
        20: 'Manakap ap potoan ong i: Mepukat karos i kapwaiadar; a da me i en pil wia?',
        21: 'Iesus kotin masani ong i: Ma koe men unsokela, u kowei, netikila om dipisou, ap kisakisaki ong me samama kan, koe ap pan aneki om pai nanlang, o kodo idauen ia do.',
        22: 'Manakap lao ronger masan pot et, ap mamauk koieila, pwe a dipisou me toto.',
        23: 'Iesus ap kotin masani ong sapwilim a tounpadak kan: Melel I indai ong komail, meid apwal ong me kapwapwa kan, en pedelong ong nan wein nanlang.',
        24: 'I pil katitiki ong komail, me mangai, kamel en tilong nan au en dikok eu, sang me kapwapwa en ko ong nan wein Kot.',
        25: 'Sapwilim a tounpadak kan lao rongadar met, ap puriamuiki kaualap indada: Ari, is me pan kak kamaurela?',
        26: 'Iesus ap kotin saupei wong irail, ap kotin masani ong irail: A so kak pan aramas, a ren Kot meakaros me kak.',
        27: 'Petrus ap sapeng poto dong i: Masani, kit likidmaliela meakaros, ap idedauen komui, a da me pan katingi kit?',
        28: 'Iesus ap kotin masani ong irail: Melel I indai ong komail, komail me idedauen ia do ni ipwi sapal, Nain aramas lao mondi pon mole lingan, komail pil pan mondi pon deun kadeik, kakaunda kainok en Israel eisokriau.',
        29: 'O meamen kasela im a kan, de ri a ol o li akan, de sam a, de in a, de a paud, de seri, de sap pweki ad ai, nan a pan ale pan pak epuki o sosoki maur soutuk.',
        30: 'A me toto men moa, pan muri; a men muri pan moa.',
    },
    20: {
        1: 'PWE wein nanlang rasong kaun pan im amen, me sangkonai ong raparapaki toundodok kai nan a mat en wain.',
        2: 'Irail lao inauki pena, me denar eu ni ran eu, ap kadar ir ala nan a mat en wain.',
        3: 'A pil kotila ni auer kasilu, ap masani akai, me momod mal nan deun saunet akan,',
        4: 'Ap masani ong irail: Komail pil kola nan mat en wain o, o meakot me pung, i pan pwain ong komail; irail ari kola.',
        5: 'A pil kola ni auer kawonu o kaduau o wiadar dueta.',
        6: 'A pil kotila ni auer eisokeu, ap diaradar akai, me momod mal, ap masani ong irail: Da me komail momodeki mal ran pon?',
        7: 'Irail potoan ong: Aki sota amen, me kadokeki kit. Ap masani ong irail: Komail pil kola nan mat en wain o, komail pan ale me pung.',
        8: 'A lao sautik penaer monsap en mat en wain masani ong a saunkoa: Kapokon pena toundodok kan o pwain ong irail. Tapiada sang ren men pwand oko lao kokodo lel men madang kan,',
        9: 'Me kadodokier ni klok eisokeu kan ap kodo, amen amen ap ale denar eu.',
        10: 'A men mas akan lao kodo, rap kiki ong, me re pan ale siki sang, a re pil aleer denar ta ieu.',
        11: 'Irail lao ale, rap lipaned ong monsap o.',
        12: 'Indada: Mepukat dodok auer ta ieu, a komui karasai kit pena; kit me dodokki apwal en ran o karakar en katipin.',
        13: 'A ap kotin sapeng masani ong amen re’rail: Kompoke pai, kaidin me sapung, me i wiai ong uk. Kita sota inauki pena denar eu?',
        14: 'Ale me om, kowei, i men pwain ong me pwand pukat rasong uk.',
        15: 'De iaduen, a sota pung, i en wiaki me udan ai, me i mauki? De por en mas om me sued pweki ai kadek?',
        16: 'Ari, me pwand akan pan moa, a me moa kan pan pwand, pwe me toto paeker, a me malaulau me piladar.',
        17: 'Iesus lao kotin kodala Ierusalem, a kotin kelepe kila tounpadak ekriamen pon al a, masani ong irail:',
        18: 'Kilang, kitail kin kodalang Ierusalem o Nain aramas pan ko ong ren samero lapalap o saunkawewe kan, o irail pan kadeikada, en kamela i.',
        19: 'O re pan pangala i ren men liki kan, pwen kapikapiti i, o kaloke, o kalopuela, a ni ran kasilu a pan maureda.',
        20: 'In en nain Sepedäus ap poto dong i, a na putak riamen iang i, pongi i o poeki okotme re a.',
        21: 'A ap kotin masani ong i: Da me koe mauki? A potoan ong i: Re kotin mueid ong ai tungol putak riamen, en mondi re ir, amen ni pali maun omui, amen ni pali maing omui nan omui wei.',
        22: 'A Iesus kotin sapeng masani: Koma sota asa, me koma poeki. Koma kak nim dal me I pan nim? Ira potoan ong: Se kak.',
        23: 'A kotin masani ong ira: Melel, komail pan tungole ai dal, a momod ni pali maun o maing i, I sota kak mueid ong, pwe pwais en irail me a onop onger sang ren Sam ai.',
        24: 'Ni en ek oko ar rongadar, ap suede kidar pirien o.',
        25: 'A Iesus kotin molipe ir do masani: Komail asa, duen saupeidi en wei pokon ar kin poe irail edi, o me lapalap akan kin manaman ong irail.',
        26: 'A duen met a sota pan wiaui nan pung omail. A me men laud nan pung omail, en papa komail.',
        27: 'O meamen re omail, me men saumas, i en lidui komail.',
        28: 'Dueta Nain aramas, me kaidin kodo, pwe aramas en papa, a pwe i en papa o kida maur a wiliandi me toto.',
        29: 'Ni arail kotila sang Ieriko, pokon kalaimun idauen la i.',
        30: 'A kilang, ol maskun riamen momod ni kailan al o. Ni ara rongadar, me Iesus kotin daulul, ira ap likelikwir indada: Maing kupura kit, ir me sapwilim en Dawid!',
        31: 'A pokon o kidau ira da, pwen nenenla. A ira kalaudela ara likelikwir indada: Maing, kupura kit, ir me sapwilim en Dawid!',
        32: 'Iesus ari kotin udi, molipe ira do masani: Da me koma mauki, I en wiai ong koma?',
        33: 'Ira potoan ong: Maing, mas at en kapad pasang!',
        34: 'Iesus ari kupuro kin ira dar o kotin sair mas ara. Mas ara ari madang pad pasanger; ira ap idauenla i.',
    },
    21: {
        1: 'NI arail koren iong Ierusalem o lel ong Petpake impan dol Oliwe, Iesus ap kotin poronela tounpadak riamen.',
        2: 'Masani ong ira: Koma ko ong nan kanim monen, a madang koma pan diar esel amen, me salidi, o na pul mi imp a, lapwa ira da, ap kare dong ia!',
        3: 'A ma meamen pan indang koma meakot, koma pan indada: Kaun o men dake, i ari pan madang kadar ira do.',
        4: 'A mepukat karos wiauier, pwen pwaida, me lokido ren saukop o me masani:',
        5: 'Kaireki nain Sion seripein: Kilang, om Nanmarki kotido re om. A kotin opampap o kaipokedi pon esel li amen.',
        6: 'A tounpadak ko lao kolar, o wiadar duen Iesus kotin masani ong ira,',
        7: 'Ira ap wado esel o na, ap irepadi po’ra arail likau kan a ap kotin kaipokedi poa.',
        8: 'O pokon kalaimunia irepadi arail likau kan nani al o, a akai paledier ran tuka kan irepadi nani al o.',
        9: 'A pokon o, me tiong moa, o me idauen, ngisingis indada: Osiana ong sapwilim en Dawid! Meid iasanai me kotido ni mar en Kaun, osiana nanlang.',
        10: 'A lao kotilong ong nan Ierusalem, toun kanim ap mokimokid indada: Is i?',
        11: 'Pokon o katitiki: Nan i Iesus, saukop en Nasaret en Kaliläa.',
        12: 'Iesus ap kotilong ong nan im en kaudok en Kot, ap kotin kase sang karos, me kin netinet nan im en kaudok, o kotin wukededi tepel en saunkawilian moni ko, o deun men netin muroi.',
        13: 'O kotin masani ong irail: A intingidi: Im ai pan adaneki im en kapakap, a komail wia kilar deu en lipirap.',
        14: 'A me maskun o me sikil akan poto dong i nan im en kaudok o; i ari kotin kakel irail adar.',
        15: 'A samero lapalap o saunkawewe kan lao kilanger manaman akan, me a kotin wiadar, o seri kan nan im en kaudok, me ngisingis indada: Osiana ong sapwilim en Dawid! Irail ap makara kidar,',
        16: 'Indai ong i: Kom sota mangi, me mepukat katitiki? A Iesus kotin masani ong irail: Ei, komail saikenta doropwe: Sang nan au en seri o me kin kang didi, ir me kotin kapwaiadar kaping eu?',
        17: 'I ari kotin muei sang irail, kotila sang nan kanim o, koti dong Petanien o pweiokidi wasa o.',
        18: 'A ni mansang ni a kotin purlang kanim o, ap men konotedar:',
        19: 'A kotin masani tuka pik pot ni kailan al o, ap kotilang i. A sota, me a kotin diaradar, pwe ta eta, ap kotin masani ong i: Koe solar pan wa kokolata! A tuka pik ap madang mongedier.',
        20: 'Tounpadak kan lao kilanger, irail ap puriamui kidar indada: Daduen tuka pik o madang mongelar.',
        21: 'A Iesus kotin sapeng masani ong irail: Melel I indai ong komail, ma komail poson, ap sota peikasal, kaidin met eta, me wiaui ong tuka pik en, me komail pan kak wiada, pwe ma komail pan indang nana wet: Mokid wei lokidokila nan madau, nan a pan pwaida.',
        22: 'O meakaros komail pan poeki ni omail kapakap, ap poson komail pan ale.',
        23: 'A lao kotilong ong nan im en kaudok o, samero lapalap akan o saumas en toun sap o ap ko dong i ni a kotin kaukawewe indada: Manaman en is, me komui wiaki mepukat? O is me ki ong komui manaman wet?',
        24: 'A Iesus kotin sapeng masani ong irail: I pan pil kalelapok meakot re omail, ma komail pan sapeng ia, I pil pan indang komail manaman en is, me I wiaki mepukat.',
        25: 'En Ioanes a paptais a tapi sang ia? Men nanlang de me ren aramas? Irail ap lamelame nan pung arail katiti, ma kitail pan inda men nanlang, a pan masani ong kitail: Da me komail so posonki i?',
        26: 'A ma kitail inda, me ren aramas, kitail masak pokon o, pwe karos kin wia saukopki Ioanes,',
        27: 'Irail ari sapeng Iesus potoan ong: Kit sota potoan. I ari pil masani ong irail: I sota pil pan indai ong komail, manaman en is, me I wiaki mepukat.',
        28: 'A iaduen omail lamelam? Aramas amen naineki ol riamen. A kola ren amen indang i: Lao, kola ran wet dodok nan ai mat en wain.',
        29: 'A sapeng indada: I sota mauki; a mur ekis a kalukila, ap koieila.',
        30: 'O a kola ren me teio indai ong pil dueta. I me sapeng indada: Ei maing; ap sota kola.',
        31: 'Ari, is re’ra, me wiadar insen en sam a? Irail potoan ong i: Men mas o. Iesus kotin masani ong irail: Melel I indai ong komail, saunopwei o me nenek kan pan mo’mail pedelong ong nan wein Kot.',
        32: 'Pwe Ioanes pwara dong komail, padapadak ong komail duen al pung, a komail sota kamelele i; a saunopwei o me nenek kan kamelele i. A komail lao kilanger, komail sota kalukila, pwen kamele i.',
        33: 'Komail rong pil apot karaseras! Kaun pan im amen padukedier mat en wain eu o kele pene, ap weiradar deun men wungid wan wain, o kauada im en daulik eu, ap kasile kin i ong saumat akai, o momaitelar nan wai.',
        34: 'A lao ansau en rak, a kadaralang saumat akan a ladu kai, pwen ale a wan wain.',
        35: 'Saumat akan ap saikedi a ladu kan; re woki amen, kamela amen, a amen me re kate.',
        36: 'A pil kadarala ladu kai, toto sang men mas, Irail ari wiai ong irail pil dueta.',
        37: 'A ikmuri a kadara wong irail na ol masani: Nan re pan masak nai ol.',
        38: 'A saumat akan lao kilanger ol o, irail ap kasokasoi nan pung arail: I me pan ale soso, ukodo kitail en kamela i, a kitail pan id ale a soso.',
        39: 'Irail ari saikedi i o kasapoke sang i nan mat en wain o, o kamela i.',
        40: 'Ari, monsap en mat en wain lao pwarado, da me a pan wiai ong saumat pukat?',
        41: 'Irail potoan ong i: A pan kamela aramas sued pukat, ap pan neki ong akai saumat a mat en wain o, me pan ki ong i wan wain ni ansau me kon ong.',
        42: 'Iesus ap kotin masani ong irail: Komail saikenta doropwer nan kisin likau kan: Takai o, me sause kan kasapokelar, ap id wialar takai en pukakaim. Mepukat wiauier ren Kaun o, men kapuriamui patail?',
        43: 'I me I indai ong komail, wein Kot pan sapadoke sang komail, ap ko ong eu kainok, me pan kida wa.',
        44: 'O meamen pupedi ong pon takai wet, pan ola, a meamen me a pan pupedi ong poa, a pan pitaki pasang i.',
        45: 'A samero lapalap o Parisär akan lao rongadar a karaseras akan, re mulikiadar, me a kotin karaserase kin irail.',
        46: 'Irail ari masamasan sili en saikidi i, a re masak aramas akan, pwe re wia kin i saukop amen.',
    },
    22: {
        1: 'A IESUS kotin sapeng o pil karaseras ong irail masani:',
        2: 'Wein nanlang rasong nanmarki amen, me kamadipe na ol ni ran en a kapapaud.',
        3: 'O a kadarala na ladu kan, pwen luke dong kamadip o, me kileledier akan; a re kang kodo.',
        4: 'A pil kadarala akai ladu masani: Kaireki me kileledier akan: Kilang, i kaonopadar ai kamadip o: nai kau ol o man wi kan me kamelar, o karos nikier, ko dong kamadip en kapapaud!',
        5: 'A irail sota insenoki, ap kowei, amen nan sap we, o amen ko ong dodok.',
        6: 'A me tei kan saikidi a ladu kan kaloke o kame ir ala.',
        7: 'Nanmarki ap makara kidar, kadarala a saunpei kan, kamela me lolap oko o isikedar ar kanim o.',
        8: 'A ap indang a ladu kan: Ari, kamadip onoper, a me kileledier akan sota war ong.',
        9: 'Komail ari kowei nan al akan, a karos me komail diar, en kalua dong kamadip o.',
        10: 'Ladu kan ap kola nani al akan, kapokon pena karos, me irail diaradar, me sued o me mau kan; kamadip ari tounlar.',
        11: 'A nanmarki lao pwarado, en kilang toun kamadip, ap diaradar aramas amen, me sota a kapwat,',
        12: 'A ap masani ong i: Kompoke pai, iaduen om kak pedelong, pwe sota om kapwat? I ari sapaimokid.',
        13: 'Nanmarki ap masani ong papa kan: Saliedi i pa o nä akan, ale o kasapokela nan rotorot liki iei wasan maiei o teterok.',
        14: 'Pwe me toto paekeredo, a me malaulau piladar.',
        15: 'Parisär ap pokon pena, kaparok pena duen ar pan kasapunga i sang a masan;',
        16: 'Irail ap kadaralang i nairail tounpadak kan iangaki ladun Erodes kan, potoan ong: Saunpadak, se asa, ir me kotin melel, o kotin kawewe melel duen al en Kot o re sota kotin kupuroki meamen, pwe re sota kotin kasampwaleki sansal en aramas.',
        17: 'Ari, re kotin masani ong kit kupur ar. Me pung, en nopwei ong nanmarki de so?',
        18: 'A Iesus lao kotin mangi ar me suet, ap masani: Malaun komail, da me komail kasongesong kin ia?',
        19: 'Kasale dong ia moni en nopwei! Irail ap potoan ong i denar eu.',
        20: 'A kotin masani ong irail: Mom en is o inting wet?',
        21: 'Irail potoan ong i: En nanmarki, a i kotin masani ong irail: Ari, komail ki ong nanmarki, me nain nanmarki, o ong Kot, me sapwilim en Kot.',
        22: 'Irail lao rongadar met, rap puriamuiki o muei sang i, o koieilar.',
        23: 'Ran ota Sadusär akai ko dong i, me kin inda, me dene me melar akan solar pan maureda, ap kalelapok re a.',
        24: 'Indada: Saunpadak, Moses masani, ma meamen melar o sota na seri, ri a ol en id paudeki a paud, pwen kaipwi ong ri a kadaudok a.',
        25: 'Ari, pwin pirien eu mi re at, ol isimen. Meseni paudeki li amen, ap melar, a sota kadaudok a, ap kakaliki ong ri a ol a paud;',
        26: 'Pil dueta kariamen o kasilimen kokola lao kaisimen.',
        27: 'A ikmuri li o pil melar.',
        28: 'Ari; ni en me melar akan ar pan iasada, a pan en is a paud ren me isimen, pwe irail karos me paudekidar i?',
        29: 'A Iesus kotin sapeng masani ong irail: Komail meid sapung pwe komail so weweki kisin likau kan de mana en Kot.',
        30: 'Pwe me mauredar akan solar pan papaud de kapapaud, pwe irail dueta tounlang en Kot akan, me mimi nanlang.',
        31: 'Komail saik doropwe duen en melar akan ar pan maureda, me lolok ong komail sang ren Kot, me kotin masani:',
        32: 'Ngai Kot en Apraam o en Isaak o en Iakop? A kaidin Kot en me melar akan, pwe en me maur akan.',
        33: 'A pokon o lao rongadar met, irail ap puriamuiki a padak.',
        34: 'A Parisär akan lao rongadar, me a kotin kadukiedier Sadusär akan, ap pokon pena.',
        35: 'Amen irail, saunkawewe men, kasongesong i potoan ong:',
        36: 'Saunpadak, kusoned da me lapalap nan kapung o?',
        37: 'A Iesus kotin masani ong i: Koe en pokeki ong Kot om Kaun mongiong om unsok, o ngen om unsok, o om lamelam unsok.',
        38: 'Iei met me moa en kusoned akan.',
        39: 'O me kariau me dueta: Koe en pok ong men imp om dueta ong pein koe.',
        40: 'Kusoned riau met me audepan kapung o saukop akan.',
        41: 'Ni en Parisär akan ar momod pena, Iesus ap kotin kainoma re’rail.',
        42: 'Masani: Da me komail lamelame duen Kristus, nain is i? Re potoan ong: Sapwilim en Dawid.',
        43: 'A kotin masani ong irail: A iaduen da me Dawid kaadaneki i Kaun reng Ngen ni a masani:',
        44: 'Kaun o kotin masani ong ai Kaun, mondi ong ni pali maun i, lao I pan wia kida om imwintiti utipan nä om?',
        45: 'A iaduen, ma Dawid kaadaneki i Kaun, a pil pan kak na ol?',
        46: 'A sota amen, me kak sapengki i meakot, o solar me idok meakot re a kokolata.',
    },
    23: {
        1: 'IESUS ap kotin kaparok ong pokon o sapwilim a tounpadak kan,',
        2: 'Masani; Saunkawewe o Parisär akan kin mondi nan deun Moses.',
        3: 'Ari, karos me re indang komail, i me komail en wia o kapwaiada, a der ale sang ar wiawia kan; pwe irail kin indada, ap sota kapwaiada.',
        4: 'Re kin pira pena kapwa en wisik me toutou melel, ap kidang pon apar en aramas, a irail sota men sairki sondin pa arail.',
        5: 'O re kin kapwaiada ar wiawia kan karos, pwe aramas en ududial. Pwe irail kin kadälape ar kisin likau en kataman o kalaudela ni kailan ar likau.',
        6: 'Irail kin ngongki mondi ni tapin tepel ni kamadip o, o leppandam nan sinakoke kan.',
        7: 'O re kin mauki, aramas en ranamau ong irail nan deun net, o aramas en wia kin ir Rapi, Rapi,',
        8: 'A komail der ngongki, aramas en wia kin komail Rapi, pwe me ta men omail Saunpadak, a komail pirien pena.',
        9: 'O komail der kaadaneki meamen sam nan sappa, pwe amen Sam omail, me kotikot nanlang.',
        10: 'O komail der ngongki, aramas en wia kin komail saumas, pwe me ta men omail Saumas: Kristus.',
        11: 'A me lapalap re omail, en omail papa.',
        12: 'Pwe me pan kasapwilada pein i, pan sapwilidi, a me pan kasapwilidi pein i, pan kasapwilada.',
        13: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Komail kin ritingidi wein nanlang mon aramas akan, pwe komail sota pan pedelong, a me men pedelong, komail sota kin mueid ong.',
        14: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Komail me ngopur sang im en li odi kan ap liliasos kapakap reirei. Omail kalokolok pan laud melel.',
        15: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Komail kin pidipidaki sed o sap, pwen wiada proselit amen, a lao wialar, komail ap pan wia kin i toun pweleko amen, me sued sang komail.',
        16: 'Suedi ong komail saunkalua maskun, komail me kin inda: Meamen kin kaukila im en kaudok, dene sota katepa, a me kin kaukila kold en im en kaudok, i me pung.',
        17: 'Komail pweipwei o maskun, pwe da me kasampwal ren kold de im en kaudok o, me kin kasarauiala kold?',
        18: 'O meamen kin kaukila pei saraui, dene sota katepa, a me kaukila mairong, me mi poa dene i me pung,',
        19: 'Komail pweipwei o maskun, pwe da me kasampwal ren mairong de pei saraui, me kin kasarauiala mairong?',
        20: 'Ari, meamen kaukila pei saraui, kin kaukila i o meakan, me mi poa.',
        21: 'O meamen kaukila im en kaudok, king kaukila i iangaki i me kotikot lole.',
        22: 'O me kaukila nanlang, kin kaukila mol en Kot o me kin kaipokedi ong poa.',
        23: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Komail kin mairongki eisokkis eu en minse, o til, o kimel, ap sota insenoki kusoned en kapung kasampwal akan: Pung, o kadek, o poson. Komail wiada mepukat, ap pil kapwaiada me tei kan!',
        24: 'Saunkalua maskun komail, me kin isenoki kisin am en wel, ap katalala kamel!',
        25: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Pwe komail kin kamakelekel kasak o dal liki, a lol me dir en me re kuliada o me sued.',
        26: 'Parisär maskun koe, kamakelekele mas lol en kasak o dal akan, pwe pali liki en pil makelekeleda!',
        27: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Komail rasong sousou kan, me sementen, me kin sansal kaselel, a lole me dir en ti en me melar akan o song en saut karos.',
        28: 'I duen komail, me sansal pung mon aramas, a lole komail me dir en malaun o sapung.',
        29: 'Suedi ong komail saunkawewe o Parisär akan, malaun komail! Pwe komail kin apapwali sousou en saukop akan o kapwataki sousou en me pung kan.',
        30: 'Ap inda: Ma kit mia ni muein sam atail akan, kit sota pan iang irail kamela saukop akan.',
        31: 'Ari, pein komail kin kadede, me komail nain me kamelar saukop akan.',
        32: 'A komail kaunsokala wiawia en sam omail akan!',
        33: 'Komail serpent o wan oter akan! Pala komail pan piti sang kadeik en nan pweleko?',
        34: 'Kilang, i me I kadara dong komail saukop akai, o me lolekong kai, o saunkawewe kai; a akai irail, me komail pan kamela, o kalopuela, o akai komail pan kaloke nan omail sinakoke kan, o komail pan paki irail sang nan eu kanim ong nan eu.',
        35: 'Pwen kapokon ong komail nta makelekel karos, me kapwilipwilidier nan sappa sang ntan Apel pung kokodo lel ntan Sakarias, nain Parakias, me komail kamelar nan pung en im en kaudok o pei saraui.',
        36: 'Melel I indai ong komail, mepukat pan pwai ong di wet.',
        37: 'O Ierusalem, Ierusalem, me kin kamela saukop akan o kate me pakadara dong uk kan; pan pak toto, me I pan kapokon pena noumail akan, duen litok kin kompwal pena na purok kan pan pa a, a komail kang.',
        38: 'Kilang, im omail pan tanla.',
        39: 'Pwe I indai ong komail, komail solar pan kilang ia sang ni ansau wet, lao komail pan inda: Meid iasanai, me kotido ni mar en Kaun o!',
    },
    24: {
        1: 'IESUS ap kotila kotiwei sang nan im en kaudok o, sapwilim a tounpadak kan ari poto dong i, pwen kasansale ong i im en kaudok o.',
        2: 'Iesus ari kotin sapeng masani ong irail: Komail so ududial mepukat karos? Melel I indai ong komail, sota eu takai pan mimi pon eu, me sota pan karongk pasang.',
        3: 'Ni a kotin kaipokedi pon dol Oliwe, tounpadak kan kelep poto dong i potoan ong: Re kotin masan dong kit ansau da, me mepukat pan pwaida o da kilel pan ar pan kotin puredo, o imwin kaua?',
        4: 'Iesus ari kotin sapeng masani ong irail: Kalaka, pwe sota amen en kotaue komail.',
        5: 'Pwe me toto pan kodo ni ad ai katiti: Ngai me Kristus o kotaue me toto.',
        6: 'Komail pan rongada duen mauin o kasokasoi pan mauin; Komail kalake, der masak; pwe mepukat pan wiaui mas, a imwi saikenta mia.',
        7: 'Pwe eu sap pan u ong eu, o eu wei ong eu; o ansaun lek, o kilitop, o rerer en sap akai pan wiaui.',
        8: 'Mepukat karos tapin kalokolok.',
        9: 'Irail ap pan pang komail lang kamakam o kame komail la; o komail pan tantat pan kainok karos pweki ad ai.',
        10: 'Me toto ap pan makarada, o amen pan pangala amen, o re pan tataki nan pung arail.',
        11: 'O saukop likam toto pan pwarada o kotaue me toto.',
        12: 'A limpok en me toto pan laula, aki sapung, me pan pwaida kaualap.',
        13: 'A me pan dadaurata lel imwi, i pan dorela.',
        14: 'A rongamau en wei o pan kalok sili nan sappa karos, pwen kadede ong wei karos, iei ansau, me imwi korendo.',
        15: 'A komail lao kilang saut akan, o ola laud mi nan wasa saraui, duen me saukop Daniel kopadar, meamen doropwe, i en weweki.',
        16: 'Me kin mi nan sap en Iudäa, ap tangala pon nana;',
        17: 'O me mi pon im, ender ko ong lole, pwen ale a kapwa sang;',
        18: 'O me mimi nan sap, ender purong ale a likau.',
        19: 'O me suedi ong irail me lisean o me kin kadidi ni ran oko!',
        20: 'Komail ari kapakap, pwe komail depa pitila ni ansaun kapau, o pil der ni ran en sapat.',
        21: 'Pwe i ansaun kamakam kaualap, sota me dueta sang ni tapin kaua kokodo lel met, pil sota pan wiaui kokolata.',
        22: 'O ma ran oko so kamalaulau la, sota uduk eu me pan dorela; a pweki me piladar akan ran oko pan kamalaulaula.',
        23: 'O ma meamen pan indang komail: Kilang iet Kristus de monen, komail der kamelele.',
        24: 'Pwe Kristus likam kai o saukop likam kai pan pwarada, o kapwareda kilel o manaman akan, pwen pil kotaueda me piladar akan, ma re kak ong.',
        25: 'Kilang, ngai me kop ong komail er.',
        26: 'Ari, ma re pan katiti ong komail: Kilang, a kotikot nan sap tan o, der koieila; kilang, a kotikot wasa rir o, der kamelele.',
        27: 'Pwe duen liol a tapida sang ni mas en lang linganla lel kapin lang, iduen en Nain aramas a pan pwarado.',
        28: 'Pwe wasa man melar mia ia, i wasa ikel pan pokon pena ia.',
        29: 'A murin kamakam o katipin pan madang rotorotala o maram pan solar lingan, o usu kan pan moredi sang nanlang, o kateng pan nanlang pan mokidada.',
        30: 'Kadapakilene pan Nain aramas ap pan pwarada nanlang, o kainok karos en sappa ap pan mamaiei, o irail pan kilang Nain aramas a kokido dapok en lang akan, me manaman o lingan kaualap.',
        31: 'O a pan kadarala na tounlang kan peuk posaune lapalap, re pan kapokon pena na me piladar akan sang pali paieu, sang ni mas en lang lel ong kapi.',
        32: 'Sang ni tuka pik o komail padakki karaseras en: Ra kan lao pilen o ta pwarada, komail asaki, me rak korendor.',
        33: 'Pil dueta komail, komail lao diar mepukat, en asa, me a korendor, a leler liman wanim.',
        34: 'Melel I indai ong komail, di wet sota pan mela, lao mepukat karos pan pwaida.',
        35: 'Lang o sappa pan poula, a ai padak sota pan poula.',
        36: 'A duen ran o auer sota amen, me asa, pil tounlang kan sasa. Sam ai ta me mangi.',
        37: 'A duen ni muein Noa iduen en Nain aramas a pan pwarado.',
        38: 'Pwe duen ni ran akan mon nolik lapalap re manga o nim, re papaud o kapapaud, lao lel ran en Noa a pedelong ong nan warim o.',
        39: 'O re sota dedeki lao lel nolik pwaida o kamop ir ala karos, iduen en Nain aramas a pan pwarado.',
        40: 'I ran o riamen pan mi nan sap; amen pan peuka sang o amen luadi.',
        41: 'Riamen pan iris nan im en plaua, amen pan peuka sang a amen luadi.',
        42: 'Komail ari masamasan, pwe komail sasa auer, me omail Kaun pan pwarado.',
        43: 'A met komail en asa, ma saumas en im o asaer auer en men lipirap pan kodo, a pan masamasan, a sota pan mueid ong kawela im a.',
        44: 'Komail ari pil masamasan, pwe Nain aramas pan kodo ni auer, me komail sota lamelame.',
        45: 'Ari, is ladu lelapok o lolekong o, me a monsap kasapwilada pon im a, pwen nene ong irail ni ansau me kon ong.',
        46: 'Ladu o meid pai, me a monsap pwara diarada i a wiawia due met!',
        47: 'Melel I indai ong komail, a pan kasapwilada i pon a dipisou karos.',
        48: 'A ma ladu sued o pan lamelame nan mongiong i: Ai monsap pwapwand kodo;',
        49: 'Ap kame a warok kan o nam o nim nan pung en me kamom sakau;',
        50: 'Monsap en ladu o ap pan pwarado ni ran eu, me a sota lamelame o ni klok, me a sasa.',
        51: 'O a pan palang pasang i o katororalang i ren me malaun akan, iei wasan maiei o teterok.',
    },
    25: {
        1: 'I ANSAU o wein nanlang me rasong li ek, me ale ar lamp akan, ap koieilang ol kamod.',
        2: 'Me limen me lolekong a me limen me lolepon.',
        3: 'Me lolepon oko wa ar lamp akan ap sota iangaki kadirepa.',
        4: 'A me lolekong ko wa ar lamp akan iangaki kadirepa.',
        5: 'A ni en ol kamod a pwapwand ir karos men mair ap mairelar.',
        6: 'A lao nan lukepan pong a lok sili: Kilang, ol kamod kotido, komail koieilang i!',
        7: 'Li karos ap pauridar kaonopadar ar lamp akan.',
        8: 'Me lolopon ap indang me lolekong kan: Komail ki dong kit kisan omail le, pwe nait lamp akan pan kunla.',
        9: 'A me lolekong kang sapeng indada: O iermen, pwe ede sola itar ong kit o komail, komail kola ren saunet netiada pein omail.',
        10: 'Ni arail kokolan net, ol kamod ap samador. Irail me onoper iang i pedelong ong nan kamadip o, wanim ap ritidier.',
        11: 'Murin ansau kis li tei ko ap pwarado indada: Maing, maing, re kotin ritingadang kit!',
        12: 'A ap sapeng indada: Melel i indang komail, i sasa komail.',
        13: 'Komail ari masamasan, pwe komail sasa ran de auer.',
        14: 'Pwe a rasong aramas amen, me pan momaitela nan wai. Ap kapokon pena na ladu kan o nek ong irail a dipisou kan.',
        15: 'A ki ong amen talent limau, a ong amen riau, a ong amen eu, duen me re itar ong, a ap madang samalar.',
        16: 'Me aleer talent limau, ap koieila dodokki o diaradar pil talent limau.',
        17: 'A me aleer riau, pil dueta, a diaradar pil riau.',
        18: 'A me aleer eu, ap koieilar sarepedier nani pwel, okilar moni en monsap o.',
        19: 'A kadekadeo a warailar monsap en ladu pukat ap puredo o kainene irail adar.',
        20: 'Me aleer talent limau ap potodo wado pil talent limau indada: Maing komui kotiki ong ia er talent limau, kom kotin masani, iet pil talent limau, me i netia kidar.',
        21: 'A monsap ap indang i: Meid mau, me koe wiadar, ladu lelapok o melel amen koe. Koe apapwali mau me tikitik o, i ap pan kasapwiladang uk pon dipisou toto, ko ong nan peren en om monsap!',
        22: 'A me aleer talent riau ap pil potodo indada: Maing komui kotiki dong ia er talent riau, kom kotin masani, iet pil talent riau, me i netia kidar.',
        23: 'A monsap ap indant i: Meid mau, me koe wiadar, ladu lelapok o melel amen koe. Koe apapwali mau me tikitik o, i ap pan kasapwiladang uk pon dipisou toto ko ong nan peren en om monsap!',
        24: 'A me aleer talent eu ap pil potodo indada: Maing, i asaer komui, me komui ol padik amen, me kin dolung sang wasa, me kaidin komui padukedier ia, o nak pena, wasa me kaidin komui kamorok ia;',
        25: 'Ngai ari masak, o koieila o okilar sapwilim omui talent nani pwel, masani, iet sapwilim omui.',
        26: 'A monsap ap sapeng indang i: Ladu sued o ponkake men koe, ma koe asaer, me i kin dolung wasa, me kaidin ngai padukedier, o nak pena wasa, me kaidin ngai kamorokier.',
        27: 'Menda koe sota ki ong saun kawilian moni nai moni, a ngai lao puredo, i ap pan ale me udan ai iangaki moni me a naitikadar.',
        28: 'Komail ari ki sang re a a talent, ap ki ong, me a talent eisok.',
        29: 'Pwe me a mia, ekis pan ko ong, pwen aneki me laud; a me sota a mia, nan a pan katia sang me mi re a.',
        30: 'A ladu me sota katepa, komail kasela nan rotorot liki, iei wasan maiei o teterok.',
        31: 'A Nain aramas lao kodo ni a lingan, o tounlang saraui kan iang i, a pan mondi pon mol en a lingan;',
        32: 'O toun sappa karos pan kapokon pena mo a. A ap pan katoror irail pasang dueta silepa o kin katorore sip ol ren li akan.',
        33: 'A pan kila na sip li akan ni pali maun, o na sip ol akan ni pali maing.',
        34: 'Nanmarki ap pan masani ong toun pali maun: Ukodo, komail kompoke pan Sam ai, sosoki wei o, me onop ong komail er sang ni tapin kaua!',
        35: 'Pwe ngai men mangadar, a komail ap kamanga ia; ngai men nim piladar, a komail ap kanim pil ia; ngai men kairu men, a komail ap kasamo ia.',
        36: 'Kiliso, a komail ap kalikauwi ia dar, ngai somaudar, a komail ap pwara dong ia; ngai salidier, a komail ap pwara dong ia.',
        37: 'Me pung kan ap pan sapeng i potoan ong: Maing, iad me se potoan ir men konot, ap potoan dong ir konot, de men konot pil, ap id konote dong ir?',
        38: 'Iad kit potoan ir men kairu, ap kasamo ir? De kiliso, ap kalikauwi ir adar?',
        39: 'Iad kit potoan ir lomum, de salidi, ap poto dong ir?',
        40: 'Nanmarki ap pan sapeng masani ong irail: Melel i indai ong komail, meakot komail wiai ong amen, ri ai ol tikitik pukat, i me komail wiai ong ia er.',
        41: 'A ap pil pan indang irail toun pali maing: Komail me riala, kowei sang ia, ko ong nan kisiniai soutuk, me onoper ong tewil o nal kan.',
        42: 'Pwe ngai men mangadar, a komail sota kamanga ia, o men nim piladar, a komail sota kanim pil ia,',
        43: 'Ngai men kairu men, a komail sota kasamo ia, kiliso, a komail sota kalikauwi ia dar, o somau, o salidi, a komail sota pwara dong ia.',
        44: 'Irail ap pil pan potoan ong: Maing, iad me se potoan ir men konot, de men konot pil, de men kairu men, de kiliso, de lomum, de salidi, ap sota papa ong ir?',
        45: 'A ap pan sapeng irail masani: Melel i indai ong komail, meakot komail sota wiai ong amen tikitik pukat, i me komail sota wiai ong ia.',
        46: 'Mepukat ap pan kolang kalokolok soutuk, a me pung kan pan maur soutuk.',
    },
    26: {
        1: 'KADEKADEO Iesus lao kaimwisokela padak pukat karos, ap kotin masani ong sapwilim a tounpadak kan:',
        2: 'Komail asa, pong ria pong pasa pan wiaui o Nain aramas pan pangala, en kalopula.',
        3: 'Samero lapalap akan o saumas akan en toun sap o ap pokon pena nan im eng samero lapalap, me maraneki Kaipas.',
        4: 'O kapukapung pena duen ar pan widingadi Iesus en kamatala.',
        5: 'A irail inda: Iermen ni ran en kamadip, pwe aramas ede moromorongada.',
        6: 'Iesus lao kotikot Petaniem nan im en Simon tuketuk,',
        7: 'Li amen ap poto dong i, wa kisin potel alapasta audaud en men kei kasampwalia ap kieledier ong pon kadokenmai, ni a kotin konot.',
        8: 'A tounpadak kan lao kilanger, ap suede kidar indada: Menda kei wet olar mal?',
        9: 'Pwe a pan netila, kareda pwai laud ap nek ong samama kan.',
        10: 'Iesus lao mangi met, ap kotin masani ong irail: Da me komail kainsensuedeki li o? Pwe me mau, me a wiai ong ia er.',
        11: 'Pwe me samama kan kin mi re omail ansau karos, a ngai sota ansau karos.',
        12: 'Pwe ni a wudok kidi pil wet pon war ai, a kaonopadar ai saredi.',
        13: 'Melel I indai ong komail, wasa karos, me rongamau wet pan kalok ia, pangada sappa pon, me a wiaer et, pil pan kaloki, pwen katamanpa.',
        14: 'Amen ekriamen, me adaneki Iudas Iskariot, ap koieila ren samero lapalap akan,',
        15: 'Indada: Da me komail pan ki dong ia, i pan panga dong komail i? Irail ari inauki ong i sip en moni sileisok.',
        16: 'A sang ni ansau o a sosong duen a pan mangai ong en pangala i.',
        17: 'Ni ran kaieu en prot somut tounpadak kan poto dong Iesus patoan ong: Ia wasa re kotin kupura, sen kaonopadang ir kamadip en pasa?',
        18: 'A kotin masani: Kola nan kanim ren ol amen indai ong i: Saunpadak o masani: Ai ansau korendor, I pan wiada kamadip en pasa re om, o ai tounpadak kan pan iang ia.',
        19: 'Tounpadak kan ap wiadar duen masan en Iesus, kaonopadar pasa.',
        20: 'A lao sautik penaer, a kaipokedi ni tepel, a ekriamen akan iang i.',
        21: 'Ni arail konokonot, a kotin masani: Melel I indai ong komail, amen komail pan pang ia la.',
        22: 'Irail ap insensued o amen amen potoan ong i indada: Maing ngai i?',
        23: 'A kotin sapeng masani: Me ian ia kaduedi nan dal o, i me pan pang ia la.',
        24: 'Pwe Nain aramas pan kokola duen a intingidier. A suedi ong aramas o, me Nain aramas pangala re a, me mau ong aramas o, ma a sota ipwidier.',
        25: 'A Iudas, me pangala i ap sapeng potoan ong indada: Rapi, ngai i? A kotin masani ong i: Koe me indada.',
        26: 'Ni arail wiadar konot. Iesus kotin limadar prot laolaoki, o pilitiki pasang, kotiki ong toupadak kan masani: Ale tungole, war ai metet.',
        27: 'A pil kotikida dal o laolaoki kotiki ong irail masani: Komail karos nim sang;',
        28: 'Pwe nt’ ai metet, udan inau kap, me pan kapwilipwilidi ong me toto, men lapwada dip.',
        29: 'A I indai ong komail, me I solar pan nim sang wan wain sang ansau wet lao lei ni ran o, me I pan pil nim nan wein Sam ai iangaki komail!',
        30: 'Irail lao melkakaki melkaka en kaping, rap kotila pon dol Oliwe.',
        31: 'Iesus ap kotin masani ong irail: Komail karos pan makar kin ia pongpong wet, pwe a intingidier: I pan kame silepa o, a pwin sip o pan more pasang.',
        32: 'A murin ai maureda, I pan ti ong mo’mail kola Kaliläa.',
        33: 'A Petrus sapeng potoan ong i: Ma karos pan makar kin ir a ngai sota pan makar.',
        34: 'Iesus kotin masani ong i: Melel I indai ong uk, pongpong wet mon malek a kakorot, koe pan kamam kin ia pan silepak.',
        35: 'Petrus potoan ong i: Ma i iang ir matala, i sota pan man kamam kin ir; iduen en tounpadak kan karos ar indinda.',
        36: 'Iesus ap kotilang wasa o me adaneki Ketsemane, a irail iang i, ap kotin masani ong tounpadak kan: Komail mondi met, lao I pan kola kapakap monen.',
        37: 'O a kotin ukadar Petrus o nain Sepedäus ol riamen, ap kotin tapiadar kupur olar o patau kaualap.',
        38: 'Iesus ap kotin masani ong irail: Ngen i ap insensuedelar kaualap ong mela. Komail pan mimieta met, iang ia masamasan.',
        39: 'O a kotila ekis wasa, ap kotin pupekidi silang i laolaoki masani: Sam ai, ma a kak, kom kotiki sang ia dal wet; ari so, kaidin ngai, komui ta en wiawia.',
        40: 'I ari kotin pure dong tounpadak kan, diar ir adar mamair, ap kotin masani ong Petrus: Komail so kak iang ia masamasan auer ta ieu?',
        41: 'Masamasan o kapakap, pwe komail de ko ong nan songesong. Nen me peik, a uduk me luet.',
        42: 'A pil kotila kariapak laolaoki masani: Sam ai, omui kupur eta, me dal wet sota kak kowei sang ia, ari I pan tungole.',
        43: 'A lao kotin puredo diar ir adar pil mamair, pwe mas arail me toutou.',
        44: 'A a kotin muei sang irail, pil kotilar laolaoki kasilepak ni masan ota.',
        45: 'Ap kotin pure dong tounpadak kan masani ong irail: Komail ari mamair o kamol. Kilang, auer leler, me Nain aramas pan pangalang pa en me dipan akan.',
        46: 'Paurida, kitail en kola, kilang, a samador, me pan pang ia la.',
        47: 'Ni a kotin mamasandar, kilang, Iudas, amen ir ekriamen oko, pwarador, pokon lapalap iang i, me wa kodlas o sokon sang ren samero lapalap akan o saumas akan en toun sap o.',
        48: 'Men pangala i ki ong ir kilel eu indada: Me I pan metik, iei I komail pan koledi.',
        49: 'I ap madang dong Iesui indada: Pong mau Rapi ap metik i.',
        50: 'A Iesus kotin masani ong i: Kompoke pai, menda koe pwarador? Irail ap por ong Iesus, saikidi i.',
        51: 'A kilang, amen irail, me iang Iesus, kapawei pa a, usadar na kodlas, pale sang salong en ladu en samero lapalap o.',
        52: 'Iesus ap kotin masani ong i: Kapure iong om kodlas nan deu a! Pwe karos, me ale kodlas, pan kamekila kodlas.',
        53: 'De koe lamelame, me I sota kak poeki ren Sam ai en kadara dong ia tounlang toto sang lekion eisokriau sama;',
        54: 'A iaduen kisin likau kak pwaida? A udan a pan wiaui duen met.',
        55: 'Ni auer ota Iesus kotin masani ong pokon o: Da, ngai lolap amen, me komail kodon aleki kodlas o sokon akan? Ni ran akan karos I mier re omail, kauwewe nan im en kaudok, a komail sota kol ia dier.',
        56: 'A mepukat karos wiauier, pwe kisin likau en saukop akan en pwaida. Tounpadak kan karos ap muei sang i tangdaui.',
        57: 'A me saikidier Iesus, ap kaluang i ren samero lapalap Kaipas, wasa saunkawewe o saumas akan pokon pena ia.',
        58: 'A Petrus idauendo i doowei sang lel tanpas en samero lapalap o pedelong ong mondi ren papa kan, pwen kilang imwin mepukat.',
        59: 'A samero lapalap akan, o saumas akan, o pwin en kapung o roporop kadede likam ong Iesus, pwen kamatala;',
        60: 'Ari, sota me irail diar. Saunkadede likam me toto, me pwarado, ari so, sota me irail diar. Ikmuri saunkadede riamen pwarado,',
        61: 'Indada: Lap en me inda: I kak ong kawela im en kaudok en Kot ap id kauada ni pong sili pong.',
        62: 'Samero lapalap ap kasinenda masani ong i: Kom sota sapengki meakot, me mepukat kin kadede ong komui?',
        63: 'A Iesus kotin nenenlata. Samero lapalap ap masani ong i: I kakau kin komui la ren Kot ieias, komui en indang kit, ma komui Kristus Sapwilim en Kot.',
        64: 'Iesus ap kotin masani ong i: Komui me inda. A I pil men kaire kin komail, sang ni ansau wet, komail pan kilang Nain aramas a pan kaipokedi ni pali maun en manaman o kokido dapok en lang akan.',
        65: 'Samero lapalap ap ter pasang, a likau kan indada: A lalaue. Menda pil akai saunkadede? Kilang, komail apton rongadar a lalaue,',
        66: 'Da me komail lamelame? Irail sapeng potoan ong: A mau ong kamela.',
        67: 'Irail ap kondipi ong silang i o pakir i, o akai pikir i ni silang i,',
        68: 'Indada: Kristus, kokop ong kit, is me pikir uk?',
        69: 'Petrus momod liki panakepir; lidu men ap ko dong i indada: Koe me pil iang Iesus en Kaliläa.',
        70: 'A i me kamamaki mo’rail karos indada: I poneponeki me koe inda.',
        71: 'A ni a pedoi wei sang nan wanim, amen lidu ap kilang i indang irail, me mi wasa o: Lap men et me pil iang Iesus en Nasaret.',
        72: 'A pil kamamki ap kaula: I sasa aramas en.',
        73: 'Mur ekis irail me u impa pil kaido indang Petrus: Melel koe amen irail, pwe ngil om kadiarok kin uk ada.',
        74: 'I ap lalaue o kaula indada: I sasa aramas en. Malek ap kakorot.',
        75: 'Petrus ap tamanda masan en Iesus, me kotin masani ong i: Mon malek a kakorot, koe pan kamam kin ia pan silepak. A ap koieila sangesang laud.',
    },
    27: {
        1: 'A LAO ran pasanger, samero lapalap akan o saumas akan en toun sap o kapukapungada duen Iesus pwen kamatala.',
        2: 'Irail lao saliedi i, ap wawei, ki ong ren kopina Pontius Pilatus.',
        3: 'A Iudas, me pangala i lao kilanger me a pakadeikadar, en kamatala, ap kalukila o purekido moni sileisok ren samero lapalap akan o saumas akan.',
        4: 'Indada: Ngai me wiadar dip, ni ai pangalar nta makelekel. A irail inda: Menda re at? Koe en pein wia.',
        5: 'I ari kasedi moni ko nan im en kaudok, ap koieilar lusiamalar.',
        6: 'A samero lapalap akan ale moni ko indada; A sota pung kitail en ki ong nan deun mairong, pwe pwain pan nta.',
        7: 'Irail ari kapukapung, ap netiadar sap en saun wia dal, wasa me men liki pan seredi ia,',
        8: 'I me wasa o adaneki sap en nta kokodo lel ran wet.',
        9: 'I dokan a pwaidar, me lokidor ren saukop Ieremia, me masani: Irail ari aleer moni sileisok i pwaine pan i, me re netiada ren men Israel.',
        10: 'O pwaine kida sap en saun wia dal, duen me Kaun o kotin masani ong ia.',
        11: 'Iesus ari kotikot mon kopina; kopina ap kainoma re a masani: Nanmarki en Sus akan komui? A Iesus kotin masani ong i: Komui me masani.',
        12: 'Samero lapalap akan o saumas akan lao karaune kin i, a sota kotin sapeng.',
        13: 'Pilatus ap masani ong i: Komui sota rong duen ar karakarauni komui kaualap?',
        14: 'I ari sota kotin masani ong i meakot. Kopina ap poneponeki kaualap.',
        15: 'Ari, ni kamadip o kopina kin lapwa ong irail amen me salidi, meamen, me re mauki,',
        16: 'A i ansau o ol amen, ad a Parapas, me salidi re’rail.',
        17: 'Irail lao pokon penaer, Pilatus ap masani ong irail: Is me komail mauki, i en lapwa dang komail, Parapas de Iesus, me maraneki Kristus?',
        18: 'Pwe a asaer, ar peirin, me re pang kilar i.',
        19: 'A lao kaipokedi pon deun kadeik, a paud ilokilang i indada: Komui der wia meakot ong ol pung men et, pwe i auramandar duen i, me i lokelokeki laud ran wet.',
        20: 'A samero lapalap akan o saumas akan sairen kila pokon o, ar poekipoeki Parapas o kamatala Iesus.',
        21: 'A kopina sapeng masani ong irail: Is re’ra, me komail mauki, i en lapwadang komail? Irail potoan ong: Parapas.',
        22: 'Pilatus ap masani ong irail: Da me i en wiaki Iesus, me maraneki Kristus? Irail karos potoan ong: A en kalopuela!',
        23: 'A kopina masani: Pwe sued da, me a wiadar? A re kalaudela ar weriwer: A pan kalopuela!',
        24: 'Pilatus lao kilang, me a sota kak wiada meakot, pwe moromorong pan wiaui, ap ale pil, omiom mo’rail masani: Ngai makelekel sang ntan ol pung men et, komail pan wia.',
        25: 'Aramas karos ap wiaki eu sapeng indada: Nta en kapokon ong kit o nait seri kan!',
        26: 'A ap lapwa dong irail Parapas, a Iesus me a woki ap mueid ong irail, en kalopuela i.',
        27: 'Nain kopina saunpei kan ap ale Iesus kalualong ong nan im en kadeik o, ap kapokon pena saunpei karos;',
        28: 'Irail ap ki sang i sapwilim a likau kan, ap id kalikauwie kida i likau waitata;',
        29: 'Ap pada al en tek eu, ap kida pon kadokenmai, o ki ong sokon apot ni lim a maun, o kelepukidi mo a o kapikapidi i indada: Iong Nanmarki en Sus akan!',
        30: 'Irail kondipe ong i, o re ale sokon o, o pokieki kadokenmai.',
        31: 'Irail lao kapiti i, ap kisang likau waitata, ap kapure ong i udan sapwilim a likau o kaluawei, pwen kalopuela.',
        32: 'Ni arail kotikot kokola, rap diarada aramas en Kirene men, me ad a Simon, i me re iton ong, en wadala sapwelim a lopu.',
        33: 'Irail lao lel ong wasa o, me ad a Kolkata, iet wewe: Wasa en pondal en monga.',
        34: 'Irail ki ong i pinika, me doleki edi. A lao kotin song kis, a sota urak.',
        35: 'Irail lao kalopuelar i, ap nek pasang sapwilim a likau kadoropwe kidar.',
        36: 'Irail ari mondi ong wasa o masamasan i.',
        37: 'O ponangin kadokenmai re pasuredier inting o, me a pukoki: Iet Nanmarki en Sus akan.',
        38: 'Lolap riamen iang i lopuelar, amen mi ni pali maun, a amen ni pali maing.',
        39: 'Me dadaulul akan lalaue i, dueduälok.',
        40: 'Katiti: Koe me kin kawela im en kaudok ap id kauada pong sili pong, en pein dore uk ala; ma Sapwilim en Kot koe, en keredi sang nin lopu en!',
        41: 'A samero lapalap, o saunkawewe, o saumas akan pil dueta kapikapiti i indada:',
        42: 'A dorelar akai, ap sota kak dorela pein i; ma i Nanmarki en Israel, i en keredi sang ni lopu en, a kitail pan kamelele i.',
        43: 'A liki Kot, i en kotin dorela, ma a kotin kupura i, pwe a indada: Ngai Sapwilim en Kot.',
        44: 'Lolap oko, me iang i lopuelar, pil lalaue i.',
        45: 'Sang ni auer kawonu lel auer kaduau rotorot kipadi sap o.',
        46: 'Ni auer kaduau Iesus ap kotin ngil laud masani: Eli, eli lama asaptani! Iet wewe: Ai Kot, ai Kot, da me komui likitmalia kin ia la?',
        47: 'Akai me u wasa o, rongadar me, ap indada: A eker Elias.',
        48: 'A amen irail pitipit tang ale lim eu, kaduedi ong nan pinika kauong ni alek apot, kidang i en urak,',
        49: 'A akai me inda: Iermen, kitail en kilang mas, ma Elias pan pwarado dorela i.',
        50: 'Iesus pil kotin ngil laud, ap kadarala ngen e.',
        51: 'A kilang, perepa likau en im en kaudok o ap dei pasang, sang pali poa lel pa, o sap rereda, o paip akai rongkilar,',
        52: 'O sousou kai sara pasang, o war en me saraui kan toto, me mamair, ap iasadar.',
        53: 'O murin ar iasadar, irail koda sang nan sousou kan, kolang kanim saraui, pwara dong me toto.',
        54: 'Senturion o me iang i sinsila Iesus, kilanger sap a rereda, o meakan, me wiauier, rap masakadar kaualap, katiti: Melel i, me Sapwilim en Kot!',
        55: 'O li toto mi kailewei, kilekilang me wiaui, iei irail, me idauendo Iesus sang Kaliläa papa i.',
        56: 'Maria men Makdala, o Maria in en Iakopus i Ioses, o in en nain Sepedäus akan mi nan pung arail.',
        57: 'A lao sautik penaer, ol kapwapwa men pwarado, men Arimatia, me ad a Iosep, me pil tounpadak en Iesus amen.',
        58: 'I ari poto dong Pilatus poeki kalep en Iesus. Pilatus ap masani, a en pangalang i.',
        59: 'Iosep ari ale kalep o, kidimiki pena likau makelekel o kaselel;',
        60: 'Ap nekidedi nan pein a sousou kap, me a weiradar nan paip; i ap kadapure ong takai kalaimun eu nan au en sousou o, ap kotila sang,',
        61: 'A Maria men Makdala, o Maria teio momod sal ong sousou o.',
        62: 'A mandan ran o, ran en kaonop, samero lapalap o Parisär akan pokon pena ren Pilatus.',
        63: 'Indada: Maing, kit tamandar, me ol sued men et katitiki ni a memaur: I pan maureda murin ran silu.',
        64: 'Komui ari masani, me ren sinsila sousou o lel ran kasilu, pwe a tounpadak kan de kodo pirapela, ap indang aramas: A kotin iasadar sang ren me melar akan, pwe pakotau wet pan sued sang men mas,',
        65: 'Pilatus masani ong irail: let silepa ko, komail kowei sinsila sousou o duen komail kak ong.',
        66: 'Irail ari koieila, kileledier takai o, o kasilaki sousou o saunpei kai.',
    },
    28: {
        1: 'RAN en sapat lao daulier, ni mansang en at en wik, Maria men Makdala, o Maria teio ap kodon ududial sousou o.',
        2: 'A kilang, sap rereda kaualap, pwe tounlang en Kaun amen, pwaradido sang nanlang o katapur sang takai o, ap kaipokedi ong poa,',
        3: 'Mom a dueta liol o a likau puetepueteta sno.',
        4: 'Silepa ko ap masapwekadar, o re likamata mela.',
        5: 'A tounlang o kotin sapeng masani ong li oko: Komail der masak pwe i asa, me koma rapaki Iesus, me lopuelar.',
        6: 'A soer met, pwe a iasadar, duen a kotin masanier. Kodo udial wasa, me Kaun nekinekidi mas o,',
        7: 'O tangwei kaireki sapwilim a tounpadak kan, me a kotin iasadar sang ren me melar akan. A kilang a pan kotin tiong mo’mail kotilang Kaliläa. I wasa komail pan diarada i. Kilang, i kop ong komail er.',
        8: 'Ira ari madang sang ni sousou o masak o peren kaualap, o tangwei kaireki ong sapwilim a tounpadak kan.',
        9: 'A ni ara kola, kaireki sapwilim a tounpadak kan, kilang, Iesus ap tu ong ira masani: Ran mau! Ira ap kai ong poridi ni aluwilu a o pongi i.',
        10: 'Iesus ap kotin masani ong ira: Der masak, kowei kaireki ri ai ol akan, pwe re en koieilang Kaliläa. I wasa re pan diar ia.',
        11: 'Ni ara kokola, kilang silepa kai ko dong kanim o kaireki samero lapalap akan karos me wiauier.',
        12: 'Irail ari pokon pena iangaki saumas akan o kapukapung, ap ki ong saunpei moni toto.',
        13: 'Indai ong irail: Komail pan inda: A tounpadak kan pwarador pong pirapela i ni at mamair.',
        14: 'A ma kopina pan rongada duen mepukat, kit ap pan sauasa komail re a.',
        15: 'Irail ari aleer moni kan o wiadar duen me re katiti ong irail. A kasoi pot et lolok sili ren Sus akan kokodo lel ran wet.',
        16: 'A tounpadak ekamen kowei ong Kaliläa, pon nana eu, me Iesus kotin kakalik ong irail er.',
        17: 'Irail lao diaradar i, re pongi ong i, a akai me peikasal.',
        18: 'Iesus ap kotido masani ong irail: Manaman en nanlang o sappa karos muei ong ia er.',
        19: 'Komail ari kola o padaki ong toun sappa karos o paptais ir ala ni mar en Sam o Na o Ngen saraui.',
        20: 'Padaki ong irail, me ren dadaurata meakan, me I kakalik ong komail er. O kilang, I pan daudaulole komail sili kokolata, lao lel sappa imwisokela.',
    },
}
